const express = require('express');
const http = require('http');
const https = require('https');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const zlib = require('zlib');
const WebSocket = require('ws');

const app = express();

// Every real response from THIS app carries this header. The Cloudflare
// Worker sitting in front of Bonto (see cloudflare-worker.js) uses its
// presence to tell "the real app answered" apart from Bonto's own branded
// loading page — that page is generated by Bonto's infrastructure before
// this code ever runs, so it can never carry this header. Set first, before
// any route, so it's on every response (including error responses) without
// having to remember to add it everywhere.
app.use((req, res, next) => {
  res.set('X-Orbit-Ready', '1');
  next();
});
