// ---------------------------------------------------------------------------
// PERSISTENCE — MongoDB Atlas when MONGODB_URI is set, so users/balances and
// game state survive a container rebuild/redeploy on hosts like Bonto that
// don't guarantee the filesystem sticks around. Falls back to the original
// local JSON files when MONGODB_URI isn't set, so nothing breaks before
// you've set up a cluster — it just won't survive a rebuild until you do.
//
// One-time setup (free, no card):
//   1. https://www.mongodb.com/cloud/atlas/register -> create a free M0 cluster
//   2. Database Access -> add a database user (username + password)
//   3. Network Access -> "Allow access from anywhere" (0.0.0.0/0) — simplest
//      for a host with a dynamic outbound IP like Bonto
//   4. Connect -> Drivers -> copy the connection string
//      (mongodb+srv://user:pass@cluster0.xxxxx.mongodb.net/...)
//   5. Set it as the MONGODB_URI environment variable in Bonto and redeploy
// Also needs the driver: run `npm install mongodb` in this project.
// ---------------------------------------------------------------------------
const { MongoClient } = require('mongodb');
const MONGODB_URI = process.env.MONGODB_URI || '';
const MONGODB_DB_NAME = process.env.MONGODB_DB || 'orbitcrash';
let mongoDb = null; // stays null (file-fallback mode) unless connectMongo() below succeeds

async function connectMongo() {
  if (!MONGODB_URI) {
    console.log("[db] MONGODB_URI not set — using local files (won't survive a container rebuild)");
    return;
  }
  try {
    const client = new MongoClient(MONGODB_URI, { serverSelectionTimeoutMS: 8000 });
    await client.connect();
    await client.db(MONGODB_DB_NAME).command({ ping: 1 });
    mongoDb = client.db(MONGODB_DB_NAME);
    console.log('[db] connected to MongoDB — data now survives a container rebuild');
  } catch (e) {
    console.error('[db] MongoDB connection failed, falling back to local files:', e.message);
    mongoDb = null;
  }
}

const DATA_DIR = process.env.DATA_DIR || __dirname;
// NOTE: intentionally NOT ".json" — the dev/hot-reload watcher on this host
// restarts the process whenever a .js/.ts/.json/.html/.css file changes, and
// this file is rewritten on every bet, cashout, login and registration. With
// a .json extension that meant every bet placed triggered a full server
// restart mid-round, wiping the in-memory round state (bets + timer). The
// content is still plain JSON, just under a non-watched extension. (Only
// touched in file-fallback mode — Mongo mode never reads/writes this file.)
const DB_FILE = path.join(DATA_DIR, 'users.dat');

let users = {}; // key = username.toLowerCase() -> {username, salt, hash, balance, lastFreeCrashDate,
                 //   refBy (key of referrer, if any), refCount (people this user referred),
                 //   refEarnings (total coins earned from referrals), refBetCount (this user's own
                 //   total bet count across all modes — used to pay their referrer every 2nd bet)}

// Generic socket-by-user map, kept in sync alongside the per-game ones below (wheelSocketsByUser
// etc.) — used for pushes that aren't tied to a specific game, like a referral payout landing on
// someone who isn't currently sitting in any particular game view.
let socketsByUser = {};

// Telegram user id (as 'tg<id>') -> referrer's user key. Set from the bot's /start <code> command,
// BEFORE that person has necessarily opened the Mini App and gotten a users[] entry of their own.
// Consumed (and deleted) the moment they actually authenticate for the first time.
let pendingReferrals = {};
async function loadUsers() {
  if (mongoDb) {
    users = {};
    try {
      const docs = await mongoDb.collection('users').find({}).toArray();
      for (const doc of docs) {
        const { _id, ...rest } = doc;
        users[_id] = rest;
      }
    } catch (e) {
      console.error('[loadUsers] Mongo read failed:', e.message);
    }
    return;
  }
  try {
    users = JSON.parse(fs.readFileSync(DB_FILE, 'utf8'));
  } catch (e) {
    users = {};
  }
}
// Backfill: every existing user gets a T Coin balance field once, so the
// trading feature can assume users[k].tcoin always exists without every
// call site needing a `|| 0` guard. Safe to call unconditionally — a no-op
// once everyone already has the field.
function backfillTCoin() {
  let changed = false;
  for (const key of Object.keys(users)) {
    if (typeof users[key].tcoin !== 'number') { users[key].tcoin = 0; changed = true; }
    if (typeof users[key].tcoinAvgBuy !== 'number') { users[key].tcoinAvgBuy = 0; changed = true; }
  }
  return changed;
}
// Writes immediately, every time — this used to be debounced 250ms behind a
// setTimeout, which meant a restart landing inside that window could lose an
// ALREADY-PROCESSED bet/cashout write (not just an in-flight round), since
// the timer never got the chance to fire. Balance correctness matters more
// here than shaving a few disk/network writes — every call site now awaits
// this, so a reply/broadcast is never sent before the write actually lands.
async function saveUsers() {
  if (mongoDb) {
    try {
      const keys = Object.keys(users);
      if (!keys.length) return;
      const ops = keys.map(key => ({
        replaceOne: { filter: { _id: key }, replacement: { _id: key, ...users[key] }, upsert: true }
      }));
      await mongoDb.collection('users').bulkWrite(ops);
    } catch (e) {
      console.error('[saveUsers] Mongo write failed:', e.message);
    }
    return;
  }
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(users));
  } catch (e) {
    console.error('[saveUsers] write failed:', e);
  }
}

function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 64).toString('hex');
}

// ---------------------------------------------------------------------------
// SESSION TOKENS
// Tokens are HMAC-signed with a secret persisted the same way as everything
// else here (Mongo when configured, else the local file), so they stay
// valid across restarts. Previously tokens were random + kept only in an
// in-memory map, so ANY restart silently broke every logged-in session: the
// page still looked logged in (token was in localStorage) but every
// bet/cashout/free-crash message was silently rejected server-side because
// the socket could never re-authenticate. That was the root cause of
// "balance doesn't move" and "free crash doesn't work".
// ---------------------------------------------------------------------------
const SECRET_FILE = path.join(DATA_DIR, 'secret.key');
let SERVER_SECRET;
async function loadOrCreateSecret() {
  if (mongoDb) {
    try {
      const doc = await mongoDb.collection('meta').findOne({ _id: 'server_secret' });
      if (doc && doc.value) { SERVER_SECRET = doc.value; return; }
    } catch (e) {
      console.error('[secret] Mongo read failed:', e.message);
    }
    SERVER_SECRET = crypto.randomBytes(32).toString('hex');
    try {
      await mongoDb.collection('meta').updateOne(
        { _id: 'server_secret' }, { $set: { value: SERVER_SECRET } }, { upsert: true }
      );
    } catch (e) {
      console.error('[secret] Mongo write failed (token will change on next restart):', e.message);
    }
    return;
  }
  try {
    SERVER_SECRET = fs.readFileSync(SECRET_FILE, 'utf8').trim();
    if (!SERVER_SECRET) throw new Error('empty');
  } catch (e) {
    SERVER_SECRET = crypto.randomBytes(32).toString('hex');
    try { fs.writeFileSync(SECRET_FILE, SERVER_SECRET); } catch (e2) { /* read-only fs: token just won't survive a restart */ }
  }
}

// ---------------------------------------------------------------------------
// GAME STATE PERSISTENCE — crash chip history + the daily stairs leaderboard
// now survive a restart instead of resetting to empty every time the host
// recycles the container. Also doubles as a safety net: any bet/stairs
// stake still marked "unresolved" in the last save gets refunded on the
// NEXT boot, in case the process died via SIGKILL (an OOM kill, e.g.) and
// never reached the graceful SIGTERM handler further down this file.
// ---------------------------------------------------------------------------
const STATE_FILE = path.join(DATA_DIR, 'game_state.dat');
async function loadGameState() {
  let s;
  if (mongoDb) {
    try {
      s = await mongoDb.collection('meta').findOne({ _id: 'game_state' });
    } catch (e) {
      console.error('[loadGameState] Mongo read failed:', e.message);
      return;
    }
    if (!s) return; // no doc yet — fresh start, nothing to restore
  } else {
    try { s = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')); }
    catch (e) { return; } // no file yet — fresh start, nothing to restore
  }
  if (Array.isArray(s.history)) history = s.history;
  if (Array.isArray(s.stairsLeaderboard)) stairsLeaderboard = s.stairsLeaderboard;
  if (typeof s.stairsLeaderboardDay === 'string') stairsLeaderboardDay = s.stairsLeaderboardDay;
  if (s.weeklyEarnings && typeof s.weeklyEarnings === 'object') weeklyEarnings = s.weeklyEarnings;
  if (typeof s.weeklyEarningsWeekKey === 'string') weeklyEarningsWeekKey = s.weeklyEarningsWeekKey;
  if (Array.isArray(s.wheelHistory)) wheelHistory = s.wheelHistory;
  if (s.wheelBiggestWin) wheelBiggestWin = s.wheelBiggestWin;
  if (typeof s.wheelBiggestWinDay === 'string') wheelBiggestWinDay = s.wheelBiggestWinDay;
  if (Array.isArray(s.ballHistory)) ballHistory = s.ballHistory;
  if (s.ballBiggestWin) ballBiggestWin = s.ballBiggestWin;
  if (typeof s.ballBiggestWinDay === 'string') ballBiggestWinDay = s.ballBiggestWinDay;
  if (Array.isArray(s.ffaHistory)) ffaHistory = s.ffaHistory;
  if (s.ffaBiggestWin) ffaBiggestWin = s.ffaBiggestWin;
  if (typeof s.ffaBiggestWinDay === 'string') ffaBiggestWinDay = s.ffaBiggestWinDay;
  if (Array.isArray(s.rouletteHistory)) rouletteHistory = s.rouletteHistory;
  if (typeof s.tradingK === 'number') tradingK = s.tradingK;
  if (Array.isArray(s.tradingPriceLog)) tradingPriceLog = s.tradingPriceLog;
  if (Array.isArray(s.tradingHistory)) tradingHistory = s.tradingHistory;
  if (s.tradingBiggestTrade) tradingBiggestTrade = s.tradingBiggestTrade;
  if (typeof s.tradingSessionVolume === 'number') tradingSessionVolume = s.tradingSessionVolume;
  if (typeof s.tradingSessionHigh === 'number') tradingSessionHigh = s.tradingSessionHigh;
  if (typeof s.tradingSessionLow === 'number') tradingSessionLow = s.tradingSessionLow;
  tradingEnsureK();
  if (s.promoCodes && typeof s.promoCodes === 'object') promoCodes = s.promoCodes;
  let refunded = false;
  if (s.leftoverBets) {
    for (const key of Object.keys(s.leftoverBets)) {
      const b = s.leftoverBets[key];
      if (b && b.status === 'active' && users[key]) { users[key].balance += b.amount; refunded = true; }
    }
  }
  if (s.leftoverStairsBets) {
    for (const key of Object.keys(s.leftoverStairsBets)) {
      if (users[key]) { users[key].balance += s.leftoverStairsBets[key]; refunded = true; }
    }
  }
  if (s.leftoverWheelBets) {
    for (const key of Object.keys(s.leftoverWheelBets)) {
      if (users[key]) { users[key].balance += s.leftoverWheelBets[key]; refunded = true; }
    }
  }
  if (s.leftoverBallBets) {
    for (const key of Object.keys(s.leftoverBallBets)) {
      if (users[key]) { users[key].balance += s.leftoverBallBets[key]; refunded = true; }
    }
  }
  if (s.leftoverMinesBets) {
    for (const key of Object.keys(s.leftoverMinesBets)) {
      if (users[key]) { users[key].balance += s.leftoverMinesBets[key].amount ?? s.leftoverMinesBets[key]; refunded = true; }
    }
  }
  if (s.leftoverUpgraderBets) {
    for (const key of Object.keys(s.leftoverUpgraderBets)) {
      const b = s.leftoverUpgraderBets[key];
      if (users[key] && b) { users[key].balance += Number(b.amount) || 0; refunded = true; }
    }
  }
  if (s.leftoverRouletteBets) {
    for (const key of Object.keys(s.leftoverRouletteBets)) {
      const b = s.leftoverRouletteBets[key];
      if (users[key] && b) { users[key].balance += Number(b.amount) || 0; refunded = true; }
    }
  }
  if (refunded) {
    console.log('[state] refunded leftover unresolved stake(s) from before the last restart');
    await saveUsers();
  }
  // bets/pendingStairsBets are guaranteed freshly-empty at this point in
  // startup (their `let` declarations ran right before this call) — writing
  // that clean state back now means a second restart landing before the
  // next natural save can never re-read the same stale leftover entries
  // and refund them a second time.
  await saveGameState();
}
async function saveGameState() {
  const payload = {
    history, stairsLeaderboard, stairsLeaderboardDay, weeklyEarnings, weeklyEarningsWeekKey,
    wheelHistory, wheelBiggestWin, wheelBiggestWinDay,
    ballHistory, ballBiggestWin, ballBiggestWinDay,
    ffaHistory, ffaBiggestWin, ffaBiggestWinDay,
    rouletteHistory,
    tradingK, tradingPriceLog, tradingHistory, tradingBiggestTrade,
    tradingSessionVolume, tradingSessionHigh, tradingSessionLow,
    promoCodes,
    leftoverBets: bets, leftoverStairsBets: pendingStairsBets, leftoverWheelBets: pendingWheelBets,
    leftoverBallBets: pendingBallBets, leftoverFfaBets: pendingFfaBets, leftoverMinesBets: pendingMinesBets, leftoverUpgraderBets: pendingUpgraderBets,
    leftoverRouletteBets: pendingRouletteBets
  };
  if (mongoDb) {
    try {
      await mongoDb.collection('meta').updateOne(
        { _id: 'game_state' }, { $set: payload }, { upsert: true }
      );
    } catch (e) {
      console.error('[saveGameState] Mongo write failed:', e.message);
    }
    return;
  }
  try {
    fs.writeFileSync(STATE_FILE, JSON.stringify(payload));
  } catch (e) {
    console.error('[saveGameState] write failed:', e);
  }
}

// =====================================================================
// TRADING — "T Coin" market.
// mainPool is NOT a separate pot of money: it's simply the live sum of
// every player's real R Coin balance right now. Buying T Coin spends a
// user's R Coin (their balance drops, so the pool shrinks) which pushes
// the price up; selling T Coin credits R Coin back (pool grows), pushing
// the price down. There is no fake liquidity/bot trading here — every
// row in the trade history is a real player action, since this moves
// real money.
// =====================================================================
const TRADING_MAX_POOL_RATIO = 0.4; // one trade can't move more than 40% of the live pool
const TRADING_COMMISSION = 0.02;    // 2% exchange fee, taken from the side received
const TRADING_BIG_TRADE_RATIO = 0.02; // trades over 2% of the pool are "big" (pinned/history highlight)
const TRADING_TICK_MS = 2000;

let tradingK = null;           // curve constant, fixed once at first boot so history is comparable
let tradingPriceLog = [];      // [{t, p}] — session price history for the chart
let tradingHistory = [];       // recent real trades: {name, act, coinAmt, atPrice, pnl, sizeMain, ts}
let tradingBiggestTrade = null;
let tradingSessionVolume = 0;  // R Coin volume traded this session
let tradingSessionHigh = null;
let tradingSessionLow = null;

function tradingMainPool() {
  let sum = 0;
  for (const key of Object.keys(users)) sum += Number(users[key].balance) || 0;
  return Math.max(1, sum); // guard against a divide-by-zero if every balance is ever 0
}
function tradingPrice(pool) {
  return tradingK / (pool == null ? tradingMainPool() : pool);
}
function tradingEnsureK() {
  if (tradingK == null) {
    tradingK = tradingMainPool();
    tradingPriceLog = [{ t: Date.now(), p: tradingPrice(tradingK) }];
    tradingSessionHigh = tradingSessionLow = tradingPrice(tradingK);
  }
}
// Stepwise integration over the live curve (price = K / pool), same shape as a
// naive AMM — gives realistic slippage on trades that are large relative to
// the pool, without needing to touch the pool more than once for the actual
// balance change (the pool itself is just users' balances, updated by the
// caller before/after this pure calculation).
function tradingSimulateBuy(pool, amtMain) {
  if (amtMain <= 0) return 0;
  let p = pool, coinsOut = 0;
  const steps = 12, step = amtMain / steps;
  for (let i = 0; i < steps; i++) {
    const price = tradingK / p;
    coinsOut += step / price;
    p -= step;
    if (p < tradingK * 0.02) p = tradingK * 0.02;
  }
  return coinsOut * (1 - TRADING_COMMISSION);
}
function tradingSimulateSell(pool, amtCoin) {
  if (amtCoin <= 0) return 0;
  let p = pool, mainOut = 0;
  const steps = 12, step = amtCoin / steps;
  for (let i = 0; i < steps; i++) {
    const price = tradingK / p;
    mainOut += step * price;
    p += step * price;
  }
  return mainOut * (1 - TRADING_COMMISSION);
}
function tradingRecordTrade(key, username, act, coinAmt, atPrice, pnl, sizeMain) {
  tradingSessionVolume += sizeMain;
  const pool = tradingMainPool();
  const isBig = sizeMain > pool * TRADING_BIG_TRADE_RATIO;
  const entry = { name: username, act, coinAmt, atPrice, pnl, sizeMain, isBig, ts: Date.now() };
  tradingHistory.unshift(entry);
  if (tradingHistory.length > 40) tradingHistory.length = 40;
  if (!tradingBiggestTrade || sizeMain > tradingBiggestTrade.sizeMain) tradingBiggestTrade = entry;
  broadcast({ type: 'trading_trade', trade: entry });
}
function tradingSnapshot() {
  tradingEnsureK();
  const pool = tradingMainPool();
  const price = tradingPrice(pool);
  return {
    price, pool, k: tradingK,
    priceLog: tradingPriceLog, history: tradingHistory, biggestTrade: tradingBiggestTrade,
    sessionVolume: tradingSessionVolume, sessionHigh: tradingSessionHigh, sessionLow: tradingSessionLow
  };
}
function tradingTick() {
  tradingEnsureK();
  const price = tradingPrice();
  tradingPriceLog.push({ t: Date.now(), p: price });
  if (tradingPriceLog.length > 20000) tradingPriceLog.shift();
  if (tradingSessionHigh == null || price > tradingSessionHigh) tradingSessionHigh = price;
  if (tradingSessionLow == null || price < tradingSessionLow) tradingSessionLow = price;
  broadcast({
    type: 'trading_tick', price, pool: tradingMainPool(),
    sessionVolume: tradingSessionVolume, sessionHigh: tradingSessionHigh, sessionLow: tradingSessionLow
  });
}

// =====================================================================
// TRADING — /trade bot command.
// Everything below renders the "T Coin" market as a chat message (photo +
// caption + inline keyboard) instead of the Mini App screen, for people
// who just want a quick look/trade from the bot's own "/" command menu.
// It reuses all the pricing/trade math above (tradingSnapshot,
// tradingSimulateBuy/Sell, tradingRecordTrade) so a trade made here and one
// made in the Mini App move the exact same live pool.
// =====================================================================

// ---- minimal, dependency-free PNG encoder (just enough for a flat RGB
// chart image — no external image library is installed in this project) ----
const PNG_CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    t[n] = c >>> 0;
  }
  return t;
})();
function pngCrc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = PNG_CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function pngChunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length, 0);
  const typeBuf = Buffer.from(type, 'ascii');
  const crc = Buffer.alloc(4); crc.writeUInt32BE(pngCrc32(Buffer.concat([typeBuf, data])), 0);
  return Buffer.concat([len, typeBuf, data, crc]);
}
// rgbBuffer: width*height*3 bytes, row-major, top-to-bottom.
function encodePng(width, height, rgbBuffer) {
  const sig = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
  const ihdrData = Buffer.alloc(13);
  ihdrData.writeUInt32BE(width, 0);
  ihdrData.writeUInt32BE(height, 4);
  ihdrData[8] = 8;  // bit depth
  ihdrData[9] = 2;  // color type: RGB
  ihdrData[10] = 0; ihdrData[11] = 0; ihdrData[12] = 0;
  const raw = Buffer.alloc(height * (1 + width * 3));
  for (let y = 0; y < height; y++) {
    const rowStart = y * (1 + width * 3);
    raw[rowStart] = 0; // no filter
    rgbBuffer.copy(raw, rowStart + 1, y * width * 3, (y + 1) * width * 3);
  }
  const idatData = zlib.deflateSync(raw);
  return Buffer.concat([
    sig, pngChunk('IHDR', ihdrData), pngChunk('IDAT', idatData), pngChunk('IEND', Buffer.alloc(0))
  ]);
}

function tradeBotChartBuffer() {
  const W = 640, H = 360;
  const rgb = Buffer.alloc(W * H * 3);
  const bg1 = [10, 15, 38], bg2 = [5, 7, 20]; // matches --bg2 -> --bg
  for (let y = 0; y < H; y++) {
    const t = y / (H - 1);
    const r = Math.round(bg1[0] + (bg2[0] - bg1[0]) * t);
    const g = Math.round(bg1[1] + (bg2[1] - bg1[1]) * t);
    const b = Math.round(bg1[2] + (bg2[2] - bg1[2]) * t);
    for (let x = 0; x < W; x++) {
      const o = (y * W + x) * 3;
      rgb[o] = r; rgb[o + 1] = g; rgb[o + 2] = b;
    }
  }
  const setPx = (x, y, color, alpha) => {
    if (x < 0 || x >= W || y < 0 || y >= H) return;
    const o = (y * W + x) * 3;
    const a = alpha == null ? 1 : alpha;
    rgb[o] = Math.round(rgb[o] * (1 - a) + color[0] * a);
    rgb[o + 1] = Math.round(rgb[o + 1] * (1 - a) + color[1] * a);
    rgb[o + 2] = Math.round(rgb[o + 2] * (1 - a) + color[2] * a);
  };
  // faint grid, same spacing feel as the Mini App's chart background
  for (let gy = 0; gy < H; gy += 40) for (let x = 0; x < W; x++) setPx(x, gy, [255, 255, 255], 0.05);
  for (let gx = 0; gx < W; gx += 54) for (let y = 0; y < H; y++) setPx(gx, y, [255, 255, 255], 0.05);

  const cutoff = Date.now() - 5 * 60 * 1000;
  let pts = tradingPriceLog.filter(p => p.t >= cutoff);
  if (pts.length < 2) pts = tradingPriceLog;
  if (!pts.length) pts = [{ t: Date.now(), p: tradingPrice() }];
  let min = Infinity, max = -Infinity;
  for (const p of pts) { if (p.p < min) min = p.p; if (p.p > max) max = p.p; }
  if (min === max) { min -= 0.0001; max += 0.0001; }
  const pad = (max - min) * 0.12;
  min -= pad; max += pad;
  const up = pts[pts.length - 1].p >= pts[0].p;
  const color = up ? [51, 255, 136] : [255, 77, 94];
  const xOf = i => Math.round((i / Math.max(1, pts.length - 1)) * (W - 1));
  const yOf = v => Math.round(H - 1 - ((v - min) / (max - min)) * (H - 1));

  // soft fill under the line
  let prevX = xOf(0), prevY = yOf(pts[0].p);
  for (let i = 1; i < pts.length; i++) {
    const x = xOf(i), y = yOf(pts[i].p);
    const steps = Math.max(1, Math.abs(x - prevX));
    for (let s = 0; s <= steps; s++) {
      const xx = Math.round(prevX + (x - prevX) * (s / steps));
      const yy = Math.round(prevY + (y - prevY) * (s / steps));
      for (let fy = yy; fy < H; fy++) setPx(xx, fy, color, 0.10 * (1 - (fy - yy) / H));
      setPx(xx, yy, color, 1); setPx(xx, yy - 1, color, 0.6); setPx(xx, yy + 1, color, 0.6);
    }
    prevX = x; prevY = y;
  }
  return encodePng(W, H, rgb);
}

// ---- Telegram sendPhoto / editMessageMedia need multipart/form-data,
// unlike every other bot call in this file which is plain JSON. ----
function telegramApiCallMultipart(method, fields, fileField, filename, fileBuffer, mime) {
  return new Promise((resolve, reject) => {
    const botToken = process.env.TELEGRAM_BOT_TOKEN;
    if (!botToken) return reject(new Error('TELEGRAM_BOT_TOKEN not configured'));
    const boundary = '----riskyBotBoundary' + crypto.randomBytes(8).toString('hex');
    const parts = [];
    for (const key of Object.keys(fields || {})) {
      if (fields[key] === undefined) continue;
      const val = typeof fields[key] === 'string' ? fields[key] : JSON.stringify(fields[key]);
      parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="${key}"\r\n\r\n${val}\r\n`));
    }
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="${fileField}"; filename="${filename}"\r\nContent-Type: ${mime}\r\n\r\n`));
    parts.push(fileBuffer);
    parts.push(Buffer.from(`\r\n--${boundary}--\r\n`));
    const body = Buffer.concat(parts);
    const req = https.request({
      hostname: 'api.telegram.org',
      path: `/bot${botToken}/${method}`,
      method: 'POST',
      headers: { 'Content-Type': `multipart/form-data; boundary=${boundary}`, 'Content-Length': body.length }
    }, (res) => {
      let data = '';
      res.on('data', (c) => { data += c; });
      res.on('end', () => {
        try {
          const parsed = JSON.parse(data);
          if (!parsed.ok) return reject(new Error(parsed.description || 'Telegram API error'));
          resolve(parsed.result);
        } catch (e) { reject(e); }
      });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

// chatId -> { key, action: 'buy'|'sell', msgId, createdAt } — set the moment
// someone taps Купить/Продать, cleared on confirm/cancel/timeout. Lets the
// very next plain-text message in that chat be read as "the amount" without
// needing a real bot-framework session/conversation layer.
let tradeBotPending = {};
setInterval(() => {
  const cutoff = Date.now() - 10 * 60 * 1000;
  for (const c of Object.keys(tradeBotPending)) if (tradeBotPending[c].createdAt < cutoff) delete tradeBotPending[c];
}, 5 * 60 * 1000);

function tradeBotUserKey(fromId) { return 'tg' + fromId; }

function tradeBotMainCaption(user) {
  const price = tradingPrice();
  return `Текущий курс: <b>${trdFmtPrice(price)}</b>\n\n` +
    `Ваш баланс R coin: <b>${Math.floor(user.balance)}</b>\n` +
    `Ваш баланс T coin: <b>${(user.tcoin || 0).toFixed(4)}</b>`;
}
function tradeBotMainKeyboard() {
  return {
    inline_keyboard: [
      [{ text: '🟢 Купить T coin', callback_data: 'trd_ask_buy' }, { text: '🔴 Продать T coin', callback_data: 'trd_ask_sell' }],
      [{ text: '🔄 Обновить', callback_data: 'trd_refresh' }]
    ]
  };
}
async function tradeBotSendMain(chatId, key, user) {
  const photo = tradeBotChartBuffer();
  const sent = await telegramApiCallMultipart('sendPhoto', {
    chat_id: chatId, caption: tradeBotMainCaption(user), parse_mode: 'HTML',
    reply_markup: tradeBotMainKeyboard()
  }, 'photo', 'chart.png', photo, 'image/png');
  return sent;
}
async function tradeBotRefreshMain(chatId, msgId, user) {
  const photo = tradeBotChartBuffer();
  // editMessageMedia replaces the photo itself (a fresh render of the real
  // current chart); the caption/keyboard come along in the same call so the
  // price text updates in lockstep with the image, in one edit.
  await telegramApiCallMultipart('editMessageMedia', {
    chat_id: chatId, message_id: msgId,
    media: { type: 'photo', media: 'attach://photo', caption: tradeBotMainCaption(user), parse_mode: 'HTML' },
    reply_markup: tradeBotMainKeyboard()
  }, 'photo', 'chart.png', photo, 'image/png');
}
async function tradeBotEditCaption(chatId, msgId, text, keyboard) {
  await telegramApiCall('editMessageCaption', {
    chat_id: chatId, message_id: msgId, caption: text, parse_mode: 'HTML',
    reply_markup: keyboard
  });
}

async function tradeBotHandleTradeCommand(msg) {
  const chatId = msg.chat && msg.chat.id;
  const fromId = msg.from && msg.from.id;
  if (!chatId || !fromId) return;
  const key = tradeBotUserKey(fromId);
  const user = users[key];
  if (!user) {
    await telegramApiCall('sendMessage', {
      chat_id: chatId,
      text: 'Сначала открой приложение хотя бы раз (кнопка «Играть» в /start), чтобы у тебя появился аккаунт — тогда /trade заработает.'
    }).catch(() => {});
    return;
  }
  delete tradeBotPending[chatId];
  await tradeBotSendMain(chatId, key, user).catch(() => {});
}

async function tradeBotHandleCallback(cq) {
  const chatId = cq.message && cq.message.chat && cq.message.chat.id;
  const msgId = cq.message && cq.message.message_id;
  const fromId = cq.from && cq.from.id;
  const data = cq.data || '';
  if (!chatId || !msgId || !fromId) { await telegramApiCall('answerCallbackQuery', { callback_query_id: cq.id }).catch(() => {}); return; }
  const key = tradeBotUserKey(fromId);
  const user = users[key];
  if (!user) {
    await telegramApiCall('answerCallbackQuery', { callback_query_id: cq.id, text: 'Открой приложение через /start, чтобы у тебя был аккаунт', show_alert: true }).catch(() => {});
    return;
  }
  await telegramApiCall('answerCallbackQuery', { callback_query_id: cq.id }).catch(() => {});

  if (data === 'trd_refresh') {
    await tradeBotRefreshMain(chatId, msgId, user).catch(() => {});
    return;
  }
  if (data === 'trd_ask_buy' || data === 'trd_ask_sell') {
    tradeBotPending[chatId] = { key, action: data === 'trd_ask_buy' ? 'buy' : 'sell', msgId, createdAt: Date.now() };
    await tradeBotEditCaption(chatId, msgId, 'Введите сумму', {
      inline_keyboard: [[{ text: '❌Отмена', callback_data: 'trd_cancel' }]]
    }).catch(() => {});
    return;
  }
  if (data === 'trd_cancel') {
    delete tradeBotPending[chatId];
    await tradeBotEditCaption(chatId, msgId, tradeBotMainCaption(user), tradeBotMainKeyboard()).catch(() => {});
    return;
  }
  if (data.startsWith('trd_confirm_buy_') || data.startsWith('trd_confirm_sell_')) {
    const isBuy = data.startsWith('trd_confirm_buy_');
    const amount = Number(data.slice(isBuy ? 'trd_confirm_buy_'.length : 'trd_confirm_sell_'.length));
    delete tradeBotPending[chatId];
    if (!amount || amount <= 0) {
      await tradeBotEditCaption(chatId, msgId, tradeBotMainCaption(user), tradeBotMainKeyboard()).catch(() => {});
      return;
    }
    if (isBuy) await tradeBotExecuteBuy(chatId, msgId, key, user, amount);
    else await tradeBotExecuteSell(chatId, msgId, key, user, amount);
    return;
  }
}

async function tradeBotExecuteBuy(chatId, msgId, key, user, amount) {
  if (amount > user.balance) {
    await tradeBotEditCaption(chatId, msgId, 'Недостаточно средств — на балансе ' + user.balance.toFixed(2), tradeBotMainKeyboard()).catch(() => {});
    return;
  }
  const pool = tradingMainPool();
  const maxTrade = pool * TRADING_MAX_POOL_RATIO;
  if (amount > maxTrade) {
    await tradeBotEditCaption(chatId, msgId, 'Слишком крупная сделка — не более ' + maxTrade.toFixed(2) + ' R за раз', tradeBotMainKeyboard()).catch(() => {});
    return;
  }
  const price = tradingPrice(pool);
  const coinsOut = tradingSimulateBuy(pool, amount);
  const tcoinBefore = user.tcoin || 0;
  user.balance = Math.round((user.balance - amount) * 100) / 100;
  user.tcoin = Math.round((tcoinBefore + coinsOut) * 10000) / 10000;
  user.tcoinAvgBuy = user.tcoin > 0 ? ((user.tcoinAvgBuy || 0) * tcoinBefore + amount) / user.tcoin : 0;
  await saveUsers();
  tradingRecordTrade(key, user.username, 'buy', coinsOut, price, null, amount);
  await saveGameState();
  const liveWs = wheelSocketsByUser[key];
  if (liveWs) { sendTo(liveWs, { type: 'balance', balance: user.balance }); sendTo(liveWs, { type: 'tcoin', tcoin: user.tcoin, avgBuy: user.tcoinAvgBuy }); }
  await tradeBotEditCaption(chatId, msgId, tradeBotMainCaption(user), tradeBotMainKeyboard()).catch(() => {});
}
async function tradeBotExecuteSell(chatId, msgId, key, user, amount) {
  if (amount > (user.tcoin || 0)) {
    await tradeBotEditCaption(chatId, msgId, 'Недостаточно T Coin — на балансе ' + (user.tcoin || 0).toFixed(4), tradeBotMainKeyboard()).catch(() => {});
    return;
  }
  const pool = tradingMainPool();
  const maxTrade = (pool * TRADING_MAX_POOL_RATIO) / tradingPrice(pool);
  if (amount > maxTrade) {
    await tradeBotEditCaption(chatId, msgId, 'Слишком крупная сделка — не более ' + maxTrade.toFixed(4) + ' T Coin за раз', tradeBotMainKeyboard()).catch(() => {});
    return;
  }
  const price = tradingPrice(pool);
  const mainOut = tradingSimulateSell(pool, amount);
  const pnl = user.tcoinAvgBuy > 0 ? ((price - user.tcoinAvgBuy) / user.tcoinAvgBuy * 100) : 0;
  user.tcoin = Math.round(((user.tcoin || 0) - amount) * 10000) / 10000;
  if (user.tcoin < 0.0001) { user.tcoin = 0; user.tcoinAvgBuy = 0; }
  user.balance = Math.round((user.balance + mainOut) * 100) / 100;
  await saveUsers();
  tradingRecordTrade(key, user.username, 'sell', amount, price, pnl, mainOut);
  await saveGameState();
  const liveWs = wheelSocketsByUser[key];
  if (liveWs) { sendTo(liveWs, { type: 'balance', balance: user.balance }); sendTo(liveWs, { type: 'tcoin', tcoin: user.tcoin, avgBuy: user.tcoinAvgBuy }); }
  await tradeBotEditCaption(chatId, msgId, tradeBotMainCaption(user), tradeBotMainKeyboard()).catch(() => {});
}

// Called for a plain-text message in a chat that has a pending Купить/Продать
// waiting on an amount. Returns true if it consumed the message (so the
// webhook's other /command branches below get skipped).
async function tradeBotHandlePendingAmount(msg) {
  const chatId = msg.chat && msg.chat.id;
  const pending = chatId != null ? tradeBotPending[chatId] : null;
  if (!pending) return false;
  const text = String(msg.text || '').trim().replace(',', '.');
  const amount = Number(text);
  const user = users[pending.key];
  if (!user || !Number.isFinite(amount) || amount <= 0) {
    await telegramApiCall('sendMessage', { chat_id: chatId, text: 'Не понял сумму, введите число.' }).catch(() => {});
    return true;
  }
  const pool = tradingMainPool();
  if (pending.action === 'buy') {
    const coinsOut = tradingSimulateBuy(pool, amount);
    await tradeBotEditCaption(chatId, pending.msgId,
      `Вы получите: <b>${coinsOut.toFixed(4)}</b> T coin`,
      { inline_keyboard: [[{ text: `купить (-${amount} R coin)`, callback_data: `trd_confirm_buy_${amount}` }, { text: '❌Отмена', callback_data: 'trd_cancel' }]] }
    ).catch(() => {});
  } else {
    const mainOut = tradingSimulateSell(pool, amount);
    await tradeBotEditCaption(chatId, pending.msgId,
      `Вы получите: <b>${mainOut.toFixed(2)}</b> R coin`,
      { inline_keyboard: [[{ text: `продать (-${amount} T coin)`, callback_data: `trd_confirm_sell_${amount}` }, { text: '❌Отмена', callback_data: 'trd_cancel' }]] }
    ).catch(() => {});
  }
  delete tradeBotPending[chatId];
  return true;
}

function makeToken(usernameKey) {
  const sig = crypto.createHmac('sha256', SERVER_SECRET).update(usernameKey).digest('hex');
  return Buffer.from(usernameKey).toString('base64url') + '.' + sig;
}
// returns the username key if the token is valid and that user still exists, else null
function verifyToken(token) {
  if (!token || typeof token !== 'string' || !token.includes('.')) return null;
  const [encKey, sig] = token.split('.');
  let key;
  try { key = Buffer.from(encKey, 'base64url').toString('utf8'); } catch (e) { return null; }
  const expected = crypto.createHmac('sha256', SERVER_SECRET).update(key).digest('hex');
  if (sig.length !== expected.length) return null;
  if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) return null;
  return users[key] ? key : null;
}

// ---------------------------------------------------------------------------
// TELEGRAM AUTH
// Validates initData per Telegram's official algorithm:
// https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app
// secret_key = HMAC_SHA256(key="WebAppData", data=<bot_token>)
// expected_hash = HEX(HMAC_SHA256(key=secret_key, data=data_check_string))
// data_check_string = every field except 'hash', "key=value" sorted
// alphabetically by key, joined with '\n'.
// Requires TELEGRAM_BOT_TOKEN set as an environment variable — without it,
// this always returns null and the client falls back to the manual
// login/register modal instead of getting stuck.
// ---------------------------------------------------------------------------
function checkTelegramAuth(initData) {
  const botToken = process.env.TELEGRAM_BOT_TOKEN;
  if (!botToken || !initData || typeof initData !== 'string') return null;
  try {
    const params = new URLSearchParams(initData);
    const hash = params.get('hash');
    if (!hash) return null;
    params.delete('hash');
    const pairs = [];
    for (const [k, v] of params.entries()) pairs.push(`${k}=${v}`);
    pairs.sort();
    const dataCheckString = pairs.join('\n');
    const secretKey = crypto.createHmac('sha256', 'WebAppData').update(botToken).digest();
    const expectedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');
    if (expectedHash.length !== hash.length) return null;
    if (!crypto.timingSafeEqual(Buffer.from(expectedHash), Buffer.from(hash))) return null;
    // reject stale/replayed initData older than 24h
    const authDate = Number(params.get('auth_date'));
    if (!authDate || (Date.now() / 1000 - authDate) > 86400) return null;
    const userJson = params.get('user');
    if (!userJson) return null;
    const user = JSON.parse(userJson);
    // start_param carries whatever payload was on the deep link that opened this Mini App
    // (e.g. a referral code) — it's covered by the same signed hash above, so it's just as
    // trustworthy as the rest of initData.
    user._startParam = params.get('start_param') || null;
    return user;
  } catch (e) {
    return null;
  }
}

app.post('/api/telegram-auth', async (req, res) => {
  const { initData } = req.body || {};
  const tgUser = checkTelegramAuth(initData);
  if (!tgUser || !tgUser.id) {
    return res.status(400).json({ error: 'Не удалось подтвердить данные Telegram — проверь TELEGRAM_BOT_TOKEN на сервере' });
  }
  const key = 'tg' + tgUser.id;
  // Telegram отдаёт нам два разных имени: "никнейм" (то, что человек указал
  // как имя профиля — first_name/last_name) и "username" (его @handle,
  // может отсутствовать). Храним оба отдельно, чтобы пользователь мог
  // переключаться между ними в настройках, не теряя вариант при смене.
  const tgNickname = [tgUser.first_name, tgUser.last_name].filter(Boolean).join(' ') || ('Игрок ' + tgUser.id);
  const tgHandle = tgUser.username || null; // без "@", может быть null
  if (!users[key]) {
    users[key] = {
      tgNickname, tgHandle, namePref: 'nickname',
      username: tgNickname, telegramId: tgUser.id, avatarUrl: tgUser.photo_url || null,
      balance: 0, lastFreeCrashDate: null,
      refBy: null, refCount: 0, refEarnings: 0, refBetCount: 0,
      tcoin: 0, tcoinAvgBuy: 0 // T Coin holdings + average buy price, for the trading screen's P&L display
    };
    // Who referred this brand-new player, if anyone? Two ways this can arrive, checked in order:
    // 1) start_param straight off a direct Mini App link (t.me/<bot>/<app>?startapp=CODE);
    // 2) a pending code recorded when they hit /start <code> on the bot itself (see webhook below),
    //    for setups where the Mini App is opened via the bot's menu button/keyboard instead.
    const refCandidate = tgUser._startParam || pendingReferrals[key] || null;
    if (refCandidate && refCandidate !== key && users[refCandidate]) {
      users[key].refBy = refCandidate;
      users[refCandidate].refCount = (users[refCandidate].refCount || 0) + 1;
    }
    delete pendingReferrals[key];
    await saveUsers();
  } else {
    // Keep name/avatar in sync in case they changed it on Telegram since last visit.
    users[key].tgNickname = tgNickname;
    users[key].tgHandle = tgHandle;
    if (!users[key].namePref) users[key].namePref = 'nickname';
    // Если раньше выбрали "показывать username", а его больше нет (сняли
    // в Telegram) — откатываемся на никнейм, чтобы не остаться без имени.
    if (users[key].namePref === 'username' && !tgHandle) users[key].namePref = 'nickname';
    users[key].username = users[key].namePref === 'username' ? tgHandle : tgNickname;
    users[key].avatarUrl = tgUser.photo_url || users[key].avatarUrl || null;
  }
  const token = makeToken(key);
  res.json({
    token, username: users[key].username, balance: users[key].balance, avatarUrl: users[key].avatarUrl || null,
    tgNickname: users[key].tgNickname, tgHandle: users[key].tgHandle, namePref: users[key].namePref
  });
});

// Переключение отображаемого имени между никнеймом и username (без "@").
app.post('/api/set-name-pref', async (req, res) => {
  const { token, pref } = req.body || {};
  const key = verifyToken(token);
  if (!key || !users[key]) return res.status(401).json({ error: 'Сессия недействительна, войдите заново' });
  const user = users[key];
  if (pref !== 'nickname' && pref !== 'username') {
    return res.status(400).json({ error: 'Некорректное значение pref' });
  }
  if (pref === 'username' && !user.tgHandle) {
    return res.status(400).json({ error: 'У тебя не задан username в Telegram' });
  }
  user.namePref = pref;
  user.username = pref === 'username' ? user.tgHandle : user.tgNickname;
  await saveUsers();
  res.json({ username: user.username, namePref: user.namePref });
});

// ---------------------------------------------------------------------------
// TELEGRAM STARS — real balance top-ups. Flow: client asks us for an
// invoice link (createInvoiceLink, currency XTR = Telegram Stars), opens it
// via tg.openInvoice() so Telegram's own native payment sheet handles the
// actual purchase, and Telegram calls OUR webhook (below) once it's really
// paid — the balance is only ever credited from that webhook, never from
// anything the client claims client-side, so a person can't just fake a
// "payment succeeded" message to give themselves free coins.
// ---------------------------------------------------------------------------
const STARS_TO_COINS = 10; // 1 Telegram Star = 10 in-app coins — never shown to the player, they only ever see the coin amount

function telegramApiCall(method, params) {
  return new Promise((resolve, reject) => {
    const botToken = process.env.TELEGRAM_BOT_TOKEN;
    if (!botToken) return reject(new Error('TELEGRAM_BOT_TOKEN not configured'));
    const body = JSON.stringify(params || {});
    const req = https.request({
      hostname: 'api.telegram.org',
      path: `/bot${botToken}/${method}`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
    }, (res) => {
      let data = '';
      res.on('data', (c) => { data += c; });
      res.on('end', () => {
        try {
          const parsed = JSON.parse(data);
          if (!parsed.ok) return reject(new Error(parsed.description || 'Telegram API error'));
          resolve(parsed.result);
        } catch (e) { reject(e); }
      });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

// payload -> { key, stars, coins, createdAt } — cleared the moment a
// payment for it is actually credited, so a replayed/duplicate webhook
// delivery for the same payload finds nothing and safely no-ops instead of
// crediting twice. Also swept for stale (>2h old, never paid) entries.
let pendingDeposits = {};
setInterval(() => {
  const cutoff = Date.now() - 2 * 60 * 60 * 1000;
  for (const p of Object.keys(pendingDeposits)) {
    if (pendingDeposits[p].createdAt < cutoff) delete pendingDeposits[p];
  }
}, 30 * 60 * 1000);

// ---------------------------------------------------------------------------
// PROMO CODES — created on the fly by @NxnaZ via a Telegram bot command
// (see the /promo handling in the webhook below), redeemed by players from
// the promo field already in the client UI. Structure:
//   promoCodes[CODE] = { reward, limit (0 = unlimited), uses, redeemedBy: {key:true} }
// Persisted through saveGameState/loadGameState like the rest of game state.
// ---------------------------------------------------------------------------
let promoCodes = {};
const PROMO_ADMIN_USERNAME = 'NxnaZ'; // only this Telegram @username can create codes via /promo

app.post('/api/promo/redeem', async (req, res) => {
  const { token, code } = req.body || {};
  const key = verifyToken(token);
  if (!key || !users[key]) return res.status(401).json({ error: 'Сессия недействительна, войдите заново' });
  const codeKey = String(code || '').trim().toUpperCase();
  if (!codeKey) return res.status(400).json({ error: 'Введи код' });
  const promo = promoCodes[codeKey];
  if (!promo) return res.status(404).json({ error: 'Такого промокода не существует' });
  if (promo.redeemedBy && promo.redeemedBy[key]) {
    return res.status(400).json({ error: 'Этот промокод уже активирован на твоём аккаунте' });
  }
  if (promo.limit && promo.uses >= promo.limit) {
    return res.status(400).json({ error: 'Лимит активаций этого промокода исчерпан' });
  }
  if (!promo.redeemedBy) promo.redeemedBy = {};
  promo.redeemedBy[key] = true;
  promo.uses = (promo.uses || 0) + 1;
  users[key].balance += promo.reward;
  await saveUsers();
  await saveGameState();
  res.json({ reward: promo.reward, balance: users[key].balance });
});

// Referral stats + share link for the "Пригласить друга" popup. The link points at the BOT
// (t.me/RiskyStarsBot?start=<key>), never at the site directly — opening it always goes through
// /start above, which is what actually attributes the referral.
const TELEGRAM_BOT_USERNAME = 'RiskyStarsBot';
app.post('/api/referral/stats', async (req, res) => {
  const { token } = req.body || {};
  const key = verifyToken(token);
  if (!key || !users[key]) return res.status(401).json({ error: 'Сессия недействительна, войдите заново' });
  const u = users[key];
  res.json({
    link: `https://t.me/${TELEGRAM_BOT_USERNAME}?start=${encodeURIComponent(key)}`,
    count: u.refCount || 0,
    earned: Math.round((u.refEarnings || 0) * 100) / 100
  });
});

// Deposits are on site-wide. The rest of the deposit flow (client modal,
// this route, Stars webhook) is untouched.
const DEPOSITS_ENABLED = true;

app.post('/api/deposit/create-invoice', async (req, res) => {
  if (!DEPOSITS_ENABLED) {
    return res.status(503).json({ error: 'Пополнение временно недоступно' });
  }
  const { token, stars } = req.body || {};
  const key = verifyToken(token);
  if (!key || !users[key]) return res.status(401).json({ error: 'Сессия недействительна, войдите заново' });
  const starsInt = Math.floor(Number(stars));
  if (!Number.isFinite(starsInt) || starsInt < 1 || starsInt > 100000) {
    return res.status(400).json({ error: 'Некорректная сумма' });
  }
  if (!process.env.TELEGRAM_BOT_TOKEN) {
    return res.status(500).json({ error: 'Пополнение временно недоступно (не настроен бот на сервере)' });
  }
  const coins = starsInt * STARS_TO_COINS;
  const payload = `dep_${key}_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`;
  try {
    const link = await telegramApiCall('createInvoiceLink', {
      title: 'Пополнение баланса',
      description: `Пополнение баланса RISKY на ${coins} монет`,
      payload,
      currency: 'XTR',
      prices: [{ label: 'Пополнение', amount: starsInt }]
    });
    pendingDeposits[payload] = { key, stars: starsInt, coins, createdAt: Date.now() };
    res.json({ link, coins });
  } catch (e) {
    res.status(500).json({ error: 'Не удалось создать счёт на оплату' });
  }
});

// Telegram calls this directly (not the client) — see setWebhook in
// bootstrap() near the bottom of the file for how it gets registered.
app.post('/telegram/webhook', async (req, res) => {
  // Optional but recommended: Telegram echoes this header back exactly as
  // set in setWebhook's secret_token, so a request without the right value
  // isn't really coming from Telegram.
  const expectedSecret = process.env.TELEGRAM_WEBHOOK_SECRET;
  if (expectedSecret && req.get('x-telegram-bot-api-secret-token') !== expectedSecret) {
    return res.sendStatus(403);
  }
  const update = req.body || {};
  try {
    if (update.callback_query) {
      await tradeBotHandleCallback(update.callback_query);
    } else if (update.message && typeof update.message.text === 'string' && !update.message.text.startsWith('/') && await tradeBotHandlePendingAmount(update.message)) {
      // handled above — the very next plain-text message after Купить/Продать is read as the amount
    } else if (update.message && typeof update.message.text === 'string' && update.message.text.startsWith('/trade')) {
      await tradeBotHandleTradeCommand(update.message);
    } else if (update.pre_checkout_query) {
      const pcq = update.pre_checkout_query;
      const pending = pendingDeposits[pcq.invoice_payload];
      if (pending) {
        await telegramApiCall('answerPreCheckoutQuery', { pre_checkout_query_id: pcq.id, ok: true });
      } else {
        await telegramApiCall('answerPreCheckoutQuery', {
          pre_checkout_query_id: pcq.id, ok: false, error_message: 'Счёт устарел, открой пополнение заново'
        });
      }
    } else if (update.message && update.message.successful_payment) {
      const sp = update.message.successful_payment;
      const pending = pendingDeposits[sp.invoice_payload];
      if (pending && users[pending.key]) {
        users[pending.key].balance += pending.coins;
        await saveUsers();
        delete pendingDeposits[sp.invoice_payload]; // idempotency: a retried webhook for this payload now finds nothing
        const liveWs = wheelSocketsByUser[pending.key];
        if (liveWs) sendTo(liveWs, { type: 'balance', balance: users[pending.key].balance });
      }
    } else if (update.message && typeof update.message.text === 'string' && update.message.text.startsWith('/start')) {
      // /start [CODE] — CODE is a referrer's own user key (see /api/referral/stats), tacked onto
      // their share link as https://t.me/RiskyStarsBot?start=CODE. Recorded here as a *pending*
      // referral keyed by this person's Telegram id, since they don't have a users[] entry yet —
      // /api/telegram-auth consumes it the moment they actually open the Mini App for the first
      // time. Always replies with a button that opens the app, referral or not.
      const msg = update.message;
      const chatId = msg.chat && msg.chat.id;
      const fromId = msg.from && msg.from.id;
      const parts = msg.text.trim().split(/\s+/);
      const payload = String(parts[1] || '').trim();
      if (payload && fromId) {
        const refKey = payload;
        const myKey = 'tg' + fromId;
        if (refKey !== myKey && users[refKey] && !users[myKey]) {
          pendingReferrals[myKey] = refKey;
        }
      }
      const publicUrl = getPublicUrl();
      if (chatId) {
        const openText = payload ? 'Тебя пригласили в RiskyStars 🎮 Жми, чтобы начать:' : 'Добро пожаловать в RiskyStars! Жми, чтобы начать:';
        await telegramApiCall('sendMessage', {
          chat_id: chatId,
          text: openText,
          reply_markup: publicUrl ? { inline_keyboard: [[{ text: '🎮 Играть', web_app: { url: publicUrl } }]] } : undefined
        }).catch(() => {});
      }
    } else if (update.message && typeof update.message.text === 'string' && update.message.text.startsWith('/deletepromo')) {
      // /deletepromo CODE — only @NxnaZ. Permanently removes the promo code
      // (including its uses/limit/redeemedBy history), so the exact same
      // CODE can immediately be recreated from scratch via /promo — as far
      // as the system is concerned it's a brand new code, redeemable again
      // by everyone including people who'd already redeemed the old one.
      const msg = update.message;
      const chatId = msg.chat && msg.chat.id;
      const fromUsername = msg.from && msg.from.username;
      const reply = (text) => { if (chatId) telegramApiCall('sendMessage', { chat_id: chatId, text }).catch(() => {}); };
      if (fromUsername !== PROMO_ADMIN_USERNAME) {
        reply('У тебя нет прав удалять промокоды.');
      } else {
        const parts = msg.text.trim().split(/\s+/).slice(1); // [CODE]
        const codeKey = String(parts[0] || '').trim().toUpperCase();
        if (!codeKey) {
          reply('Формат: /deletepromo КОД\nПример: /deletepromo WELCOME100');
        } else if (!promoCodes[codeKey]) {
          reply(`Промокода "${codeKey}" не существует.`);
        } else {
          delete promoCodes[codeKey];
          await saveGameState();
          reply(`Промокод "${codeKey}" удалён навсегда. Можно создать заново с тем же названием через /promo.`);
        }
      }
    } else if (update.message && typeof update.message.text === 'string' && update.message.text.startsWith('/promo')) {
      // /promo CODE REWARD LIMIT — only @NxnaZ can create promo codes this
      // way. REWARD is coins granted per activation, LIMIT is the total
      // number of accounts that may redeem it (0 = unlimited). Codes are
      // always one-time-per-account regardless of LIMIT — enforced in
      // /api/promo/redeem above, not here.
      const msg = update.message;
      const chatId = msg.chat && msg.chat.id;
      const fromUsername = msg.from && msg.from.username;
      const reply = (text) => { if (chatId) telegramApiCall('sendMessage', { chat_id: chatId, text }).catch(() => {}); };
      if (fromUsername !== PROMO_ADMIN_USERNAME) {
        reply('У тебя нет прав создавать промокоды.');
      } else {
        const parts = msg.text.trim().split(/\s+/).slice(1); // [CODE, REWARD, LIMIT]
        const codeKey = String(parts[0] || '').trim().toUpperCase();
        const reward = Math.floor(Number(parts[1]));
        const limit = Math.floor(Number(parts[2]));
        if (!codeKey || !Number.isFinite(reward) || reward <= 0 || !Number.isFinite(limit) || limit < 0) {
          reply('Формат: /promo КОД НАГРАДА ЛИМИТ (лимит 0 = без ограничений).\nПример: /promo WELCOME100 100 0');
        } else if (promoCodes[codeKey]) {
          reply(`Промокод "${codeKey}" уже существует.`);
        } else {
          promoCodes[codeKey] = { reward, limit, uses: 0, redeemedBy: {} };
          await saveGameState();
          reply(`Промокод "${codeKey}" создан: +${reward} монет, лимит активаций: ${limit || 'без ограничений'}.`);
        }
      }
    }
  } catch (e) {
    // swallow — still answer 200 below so Telegram doesn't hammer retries
    // over something that was already handled or partially handled
  }
  res.sendStatus(200);
});

// ---------------------------------------------------------------------------
// AUTH ROUTES — Telegram-only now (see /api/telegram-auth above). The old
// password-based /api/register and /api/login are gone: there's no manual
// signup path left in the UI, every identity comes from Telegram initData.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// SHARED GAME MATH
// ---------------------------------------------------------------------------
const GROWTH_K1 = 0.05;
const GROWTH_K2 = 0.008;
const MAX_MULTIPLIER = 999999;
const HOUSE_EDGE = 0.015;
const BETTING_MS = 10000;
const CRASH_MIN_BET = 1; // matches the client's own minimum (setBet/halveBet/setBetMax all floor at 1)
const FREE_MIN_CASHOUT_MULT = 1.10; // can't cash out before this multiplier

// Free crash bet reel: instead of a fixed 100, the free round's stake is
// now picked by a weighted spin (1/5/10/25/50/75/100 — higher value =
// rarer), ported from free-crash-reel-mockup.html. The server is the one
// that actually rolls the weighted pick (never the client) since it
// determines a real payout; the client only plays a matching visual spin
// that lands on whatever amount the server already decided — same
// "server decides, client just animates the reveal" pattern the main
// crash's own crashPoint already uses.
const FREE_REEL_VALUES = [
  { v: 1,   weight: 42 },
  { v: 5,   weight: 28 },
  { v: 10,  weight: 14 },
  { v: 25,  weight: 8 },
  { v: 50,  weight: 4.5 },
  { v: 75,  weight: 2.5 },
  { v: 100, weight: 1 },
];
const FREE_REEL_TOTAL_WEIGHT = FREE_REEL_VALUES.reduce((s, x) => s + x.weight, 0);
function pickFreeReelAmount() {
  let r = Math.random() * FREE_REEL_TOTAL_WEIGHT;
  for (const item of FREE_REEL_VALUES) {
    if (r < item.weight) return item.v;
    r -= item.weight;
  }
  return FREE_REEL_VALUES[0].v;
}
const FREE_REEL_SPIN_MS = 5200;  // must match .free-reel-strip.spinning's CSS transition duration exactly
const FREE_REEL_PAUSE_MS = 3000; // the requested pause after the reel visually lands before the round actually starts

// ---------------------------------------------------------------------------
// RISKY — a single filler bot shared by Wheel of Fortune and Ball of Fate.
// Both games only start their countdown once 2+ bettors are in the pot, so
// a lone real player would otherwise just sit stuck on "waiting for
// players" — Risky bets a random whole number 1-100 shortly after each
// round opens, which lets the round actually get moving as soon as one
// real player joins.
//
// Risky has no real balance (no entry in `users`): if it wins the pot, the
// payout branch's `users[key]` lookup simply misses and nothing is paid
// out to anyone — the house keeps it. If it loses, the real winner is paid
// the FULL pot including Risky's stake, exactly like beating any other
// real player. Its avatar is embedded as a data URI so it renders
// everywhere avatars do (Ball's canvas clips it into a circle already;
// nothing extra needed to make it "round").
// ---------------------------------------------------------------------------
const RISKY_BOT_NAME = 'Risky';
const RISKY_BOT_KEY = 'bot:Risky';
const RISKY_BOT_AVATAR_URL = 'data:image/png;base64,';
function riskyBotAmount(){ return 1 + Math.floor(Math.random() * 50); } // whole number, 1-50
const RISKY_BOT_JOIN_CHANCE = 0.10; // Risky only actually places a bet in 10% of rounds — same idea as BOT_JOIN_CHANCE (Crash) / ROULETTE_BOT_JOIN_CHANCE (Roulette)

// ---------------------------------------------------------------------------
// WHEEL OF FORTUNE — a single shared pot-takes-all round, same shape as the
// mockup (15s betting window that only actually starts counting once 2+
// bets are in, a spin picked by ONE weighted random draw since slice size
// == amount/pot already IS the weighted draw, winner takes the whole pot),
// just with every bettor a real connected player instead of bots. The
// server is authoritative for the whole round (bets, timer, spin target,
// winner) and broadcasts it to everyone; the client only renders it.
// ---------------------------------------------------------------------------
const WHEEL_BETTING_MS = 15000;
const WHEEL_SPIN_MIN_MS = 6500;
const WHEEL_SPIN_MAX_MS = 7500;
const WHEEL_MIN_BET = 1;
const WHEEL_MAX_ADDS = 5; // how many times one user can add to their own bet in a single round — matches the client's own cap, and Ball of Fate / FFA Arena
const WHEEL_SLICE_COLORS = ['#33f4e0','#ffb545','#ff4d5e','#7CFF9E','#c48bff','#ff8fd6','#5ec8ff','#ffe066','#ff8a3d','#8bd4ff'];

// Wheel of Fortune and Ball of Fate used to hand out colors by cycling
// through the 10-color WHEEL_SLICE_COLORS list in strict join order — so
// whichever slot a player landed in (1st bettor, 2nd bettor, ...) always
// got the exact same color, round after round. That's what read as "the
// same colors keep coming up". This is a much larger pool (60+ distinct
// hues, spread via golden-angle stepping so they're spread around the
// color wheel rather than clustered) that both games now draw from
// randomly per bet, only constrained to avoid whatever color(s) are
// already taken by other bets in that SAME round.
function hslToHex(h, s, l) {
  s /= 100; l /= 100;
  const k = n => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = n => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
  const toHex = x => Math.round(255 * x).toString(16).padStart(2, '0');
  return '#' + toHex(f(0)) + toHex(f(8)) + toHex(f(4));
}
const RANDOM_COLOR_POOL = Array.from({ length: 60 }, (_, i) =>
  hslToHex((i * 137.508) % 360, 72, 58)
);
function pickRandomUnusedColor(usedColors) {
  const used = new Set(usedColors);
  const free = RANDOM_COLOR_POOL.filter(c => !used.has(c));
  // Pool has 60 colors — running out means 60+ simultaneous bettors in one
  // round, which shouldn't happen, but fall back to allowing a repeat
  // rather than ever failing to assign a color.
  const pool = free.length ? free : RANDOM_COLOR_POOL;
  return pool[Math.floor(Math.random() * pool.length)];
}

let wheelPhase = 'betting'; // 'betting' | 'spinning'
let wheelBets = []; // { key, username, amount, color }
let wheelCountdownStarted = false;
let wheelBettingEndTs = 0;
let wheelPhaseTimer = null; // the setTimeout driving betting -> spinning, rescheduled whenever the deadline moves
let wheelRotationDeg = 0;
let wheelSpinStartTs = 0, wheelSpinDurationMs = 0, wheelSpinStartRotation = 0, wheelSpinTargetRotation = 0;
let wheelWinner = null;
let wheelHistory = [];
let wheelBiggestWin = null;
let wheelBiggestWinDay = null;
function wheelBiggestWinEnsureDay() {
  const today = mskDateString(Date.now());
  if (wheelBiggestWinDay !== today) { wheelBiggestWinDay = today; wheelBiggestWin = null; }
}
// key -> amount staked this round, cleared once the round resolves (win or
// lose — unlike Stairs there's no per-bet payout to reconcile
// against, the whole round settles at once). Refunded on shutdown the same
// way pendingStairsBets is.
let pendingWheelBets = {};
let wheelAddCounts = {}; // key -> how many times they've added this round, reset every wheelStartBettingRound

function wheelPotTotal(){ return wheelBets.reduce((s,b)=>s+b.amount, 0); }
function wheelNextColor(){ return pickRandomUnusedColor(wheelBets.map(b => b.color)); }

// Recomputes each bet's slice boundaries (0-360deg) from current amounts —
// this IS the weighted-draw setup: slice size == amount/pot exactly, so a
// single uniform-random angle draw against these ranges is a fair weighted
// pick with no separate "choose winner then find their slice" step needed.
function wheelBetsList(){
  const pot = wheelPotTotal();
  let cum = 0;
  return wheelBets.map(b => {
    const frac = pot > 0 ? b.amount/pot : 0;
    const startDeg = cum*360;
    cum += frac;
    const endDeg = cum*360;
    return { username: b.username, amount: b.amount, color: b.color, startDeg, endDeg };
  });
}

function wheelScheduleTransition(){
  if (wheelPhaseTimer) { clearTimeout(wheelPhaseTimer); wheelPhaseTimer = null; }
  if (wheelPhase !== 'betting' || !wheelCountdownStarted) return;
  const delay = Math.max(0, wheelBettingEndTs - Date.now());
  wheelPhaseTimer = setTimeout(() => {
    if (wheelPhase === 'betting') wheelStartSpin();
  }, delay);
}

function wheelStartBettingRound(){
  wheelPhase = 'betting';
  wheelBets = [];
  wheelCountdownStarted = false;
  wheelBettingEndTs = 0;
  wheelAddCounts = {};
  if (wheelPhaseTimer) { clearTimeout(wheelPhaseTimer); wheelPhaseTimer = null; }
  wheelBiggestWinEnsureDay();
  broadcast({ type: 'wheel_round_start', bets: wheelBetsList(), history: wheelHistory, biggestWin: wheelBiggestWin });
  wheelScheduleBot();
}

// Risky joins a random moment early in the round (not always first-in-frame,
// reads more like an actual player trickling in) — but only if the round is
// still open for bets by the time its delay elapses.
function wheelScheduleBot(){
  if (Math.random() >= RISKY_BOT_JOIN_CHANCE) return; // sits this round out
  const delay = 400 + Math.random() * 3500;
  setTimeout(() => {
    if (wheelPhase !== 'betting') return;
    wheelPlaceBet(RISKY_BOT_KEY, RISKY_BOT_NAME, riskyBotAmount());
  }, delay);
}

// amount is already deducted from the user's balance by the caller (the
// 'wheel_bet' handler below) — this only updates round state and the
// betting-window timer, then broadcasts the new state to everyone.
function wheelPlaceBet(key, username, amount){
  const existing = wheelBets.find(b => b.key === key);
  if (existing) { existing.amount = Math.round((existing.amount + amount)*100)/100; }
  else { wheelBets.push({ key, username, amount, color: wheelNextColor() }); }

  if (!wheelCountdownStarted && wheelBets.length >= 2 && wheelPhase === 'betting') {
    wheelCountdownStarted = true;
    wheelBettingEndTs = Date.now() + WHEEL_BETTING_MS;
  }

  // Same two-factor extension as the mockup: bigger share of the pot ->
  // bigger extension, and the closer to the buzzer it lands the more of
  // that extension actually applies (decays to 0 once 20s+ remain).
  if (wheelCountdownStarted && wheelPhase === 'betting') {
    const remainMs = wheelBettingEndTs - Date.now();
    const NEAR_END_MS = 20000;
    if (remainMs > 0 && remainMs <= NEAR_END_MS) {
      const pot = wheelPotTotal();
      const frac = pot > 0 ? amount/pot : 0;
      const baseExtensionSec = Math.max(0, Math.min(10, 11.25*frac - 0.125));
      const remainSec = remainMs/1000;
      const decay = Math.max(0, 1 - 0.05*remainSec);
      const extensionSec = baseExtensionSec * decay;
      if (extensionSec > 0) wheelBettingEndTs += extensionSec*1000;
    }
  }

  wheelScheduleTransition();
  broadcast({ type: 'wheel_bet_update', bets: wheelBetsList(), bettingEndTs: wheelBettingEndTs, countdownStarted: wheelCountdownStarted });
}

function wheelStartSpin(){
  const pot = wheelPotTotal();
  if (pot <= 0) { wheelStartBettingRound(); return; }
  wheelPhase = 'spinning';

  const targetLocalDeg = Math.random()*360; // single weighted draw — slice size == bet share
  const slices = wheelBetsList();
  const winnerSlice = slices.find(b => targetLocalDeg >= b.startDeg && targetLocalDeg < b.endDeg) || slices[slices.length-1];
  const winnerBet = wheelBets.find(b => b.username === winnerSlice.username);

  const desiredMod = (360 - targetLocalDeg) % 360;
  const currentMod = ((wheelRotationDeg % 360) + 360) % 360;
  const extraSpins = 5 + Math.floor(Math.random()*3); // 5-7 full extra spins
  const forwardDelta = (desiredMod - currentMod + 360) % 360;

  wheelSpinStartRotation = wheelRotationDeg;
  wheelSpinTargetRotation = wheelRotationDeg + extraSpins*360 + forwardDelta;
  wheelSpinDurationMs = WHEEL_SPIN_MIN_MS + Math.random()*(WHEEL_SPIN_MAX_MS - WHEEL_SPIN_MIN_MS);
  wheelSpinStartTs = Date.now();
  wheelWinner = {
    key: winnerBet.key, username: winnerBet.username, color: winnerBet.color,
    amount: winnerBet.amount, pot, chancePct: pot > 0 ? (winnerBet.amount/pot*100) : 0
  };

  broadcast({
    type: 'wheel_spin_start', bets: slices,
    spinStartTs: wheelSpinStartTs, spinDurationMs: wheelSpinDurationMs,
    spinStartRotation: wheelSpinStartRotation, spinTargetRotation: wheelSpinTargetRotation
  });

  setTimeout(wheelFinishSpin, wheelSpinDurationMs);
}

async function wheelFinishSpin(){
  const w = wheelWinner;
  if (w && users[w.key]) {
    users[w.key].balance += w.pot;
    recordEarnings(w.username, w.pot - w.amount);
    await saveUsers();
    const winnerWs = wheelSocketsByUser[w.key];
    if (winnerWs) sendTo(winnerWs, { type: 'balance', balance: users[w.key].balance });
  }
  wheelRotationDeg = wheelSpinTargetRotation;
  pendingWheelBets = {}; // round is fully settled — nothing left unresolved to refund
  await saveGameState();

  if (w) {
    wheelHistory.unshift({ username: w.username, amount: w.pot, color: w.color, chancePct: w.chancePct });
    wheelHistory = wheelHistory.slice(0, 10);
    wheelBiggestWinEnsureDay();
    if (!wheelBiggestWin || w.pot > wheelBiggestWin.amount) {
      wheelBiggestWin = { username: w.username, amount: w.pot, chancePct: w.chancePct, color: w.color };
    }
    broadcast({ type: 'wheel_spin_result', winner: w, history: wheelHistory, biggestWin: wheelBiggestWin });
  }

  setTimeout(wheelStartBettingRound, 4800);
}

// key -> ws, kept in sync on auth/close so wheelFinishSpin can push a
// balance update to the winner even though they aren't the one whose
// message triggered the round to resolve (the round timer is).
let wheelSocketsByUser = {};

// ---------------------------------------------------------------------------
// BALL OF FATE ("Шар судьбы") — each bettor gets a zone on a square field
// sized to their share of the pot (100% of the pot -> 100% of the field),
// assigned as an organic contiguous blob (randomized grid-growth), not a
// clean rectangle or pizza slice. After betting closes, a ball appears, a
// decorative arrow spins and locks onto a random direction, then the ball
// launches with NO gravity, bounces elastically off the four walls, and
// slowly loses speed to friction each tick until it stops. Whoever's zone
// the ball is mostly resting in when it fully stops takes the whole pot.
// ---------------------------------------------------------------------------
const BALL_MIN_BET = 1;
const BALL_BETTING_MS = 15000;
const BALL_ARROW_SPIN_MS = 1500;   // decorative suspense before launch
const BALL_TICK_MS = 50;
const BALL_FIELD = 100;            // logical field is a 0..100 square, both server and client agree on this
const BALL_RADIUS = 4;             // logical units
const BALL_SPEED = 14;             // logical units/tick at launch (was 6.5 — felt weak)
const BALL_FRICTION = 0.975;       // per-tick speed decay — this IS the only thing that ever slows it, no gravity
                                    // (tightened from 0.985 to keep total roll time sane now that SPEED is higher)
const BALL_STOP_SPEED = 0.03;      // below this, the ball counts as stopped. Dropped a lot from the old 0.25:
                                    // that value froze the ball while it was still visibly gliding at a
                                    // noticeable speed — one tick moving, the next tick dead stop, which read
                                    // as an abrupt slam rather than a smooth fade to rest. At 0.03 the last bit
                                    // of motion is essentially imperceptible before it locks.

let ballPhase = 'betting'; // 'betting' | 'arming' | 'rolling'
let ballBets = []; // { key, username, amount, color }
let ballCountdownStarted = false;
let ballBettingEndTs = 0;
let ballPhaseTimer = null;
let ballSites = []; // [{x,y,w}] in the 0..100 field, index-aligned with ballBets — see ballAssignZones
let ball = null; // { x, y, vx, vy }
let ballTickTimer = null;
let ballHistory = [];
let ballBiggestWin = null;
let ballBiggestWinDay = null;
function ballBiggestWinEnsureDay() {
  const today = mskDateString(Date.now());
  if (ballBiggestWinDay !== today) { ballBiggestWinDay = today; ballBiggestWin = null; }
}
let pendingBallBets = {};
let ballSocketsByUser = {};
const BALL_MAX_ADDS = 5; // how many times one user can add to their own bet in a single round — matches the client's own cap
let ballAddCounts = {}; // key -> how many times they've added this round, reset every ballStartBettingRound

function ballPotTotal(){ return ballBets.reduce((s,b)=>s+b.amount, 0); }
function ballNextColor(){ return pickRandomUnusedColor(ballBets.map(b => b.color)); }
function ballBetsList(){ return ballBets.map(b => ({ username: b.username, amount: b.amount, color: b.color, avatarUrl: b.avatarUrl || null })); }

function ballScheduleTransition(){
  if (ballPhaseTimer) { clearTimeout(ballPhaseTimer); ballPhaseTimer = null; }
  if (ballPhase !== 'betting' || !ballCountdownStarted) return;
  const delay = Math.max(0, ballBettingEndTs - Date.now());
  ballPhaseTimer = setTimeout(() => { if (ballPhase === 'betting') ballStartRound(); }, delay);
}

function ballStartBettingRound(){
  ballPhase = 'betting';
  ballBets = [];
  ballCountdownStarted = false;
  ballBettingEndTs = 0;
  ballSites = [];
  ballAddCounts = {};
  if (ballPhaseTimer) { clearTimeout(ballPhaseTimer); ballPhaseTimer = null; }
  if (ballSoloTimer) { clearTimeout(ballSoloTimer); ballSoloTimer = null; }
  ballBiggestWinEnsureDay();
  broadcast({ type: 'ball_round_start', bets: ballBetsList(), history: ballHistory, biggestWin: ballBiggestWin });
  ballScheduleBot();
}

// Same idea as Wheel's wheelScheduleBot() — Risky joins at a random moment
// early in the round rather than always being the very first bet.
function ballScheduleBot(){
  if (Math.random() >= RISKY_BOT_JOIN_CHANCE) return; // sits this round out
  const delay = 400 + Math.random() * 3500;
  setTimeout(() => {
    if (ballPhase !== 'betting') return;
    ballPlaceBet(RISKY_BOT_KEY, RISKY_BOT_NAME, riskyBotAmount(), RISKY_BOT_AVATAR_URL);
  }, delay);
}

// amount already deducted from the user's balance by the 'ball_bet' handler
// below — this only updates round state and the betting-window timer, same
// two-factor extension as Wheel (bigger share + closer to the buzzer ->
// bigger effective extension).
const BALL_SOLO_TIMEOUT_MS = 7 * 60 * 1000; // no 2nd bettor within this long -> auto-refund and reset
let ballSoloTimer = null;

async function ballRefundSoloBet(){
  // Only a solo bettor can ever be in this state — if a 2nd person joined,
  // ballCountdownStarted flips true and this timer gets cleared. Refund
  // and fully reset the round so no stake is EVER left stuck with no way
  // to resolve, which is what was happening before this existed: a lone
  // bettor's stake sat in ballBets forever, already deducted, with the
  // round permanently stuck on "waiting for players".
  if (ballPhase !== 'betting' || ballCountdownStarted || ballBets.length !== 1) return;
  const b = ballBets[0];
  if (users[b.key]) {
    users[b.key].balance += b.amount;
    await saveUsers();
    const soloWs = ballSocketsByUser[b.key];
    if (soloWs) {
      sendTo(soloWs, { type: 'balance', balance: users[b.key].balance });
      sendTo(soloWs, { type: 'ball_solo_refund', amount: b.amount });
    }
  }
  delete pendingBallBets[b.key];
  await saveGameState();
  ballStartBettingRound();
}

function ballPlaceBet(key, username, amount, avatarUrlOverride){
  const existing = ballBets.find(b => b.key === key);
  if (existing) { existing.amount = Math.round((existing.amount + amount)*100)/100; }
  else { ballBets.push({ key, username, amount, color: ballNextColor(), avatarUrl: avatarUrlOverride || (users[key] && users[key].avatarUrl) || null }); }

  if (!ballCountdownStarted && ballBets.length >= 2 && ballPhase === 'betting') {
    ballCountdownStarted = true;
    ballBettingEndTs = Date.now() + BALL_BETTING_MS;
    if (ballSoloTimer) { clearTimeout(ballSoloTimer); ballSoloTimer = null; }
  } else if (ballBets.length === 1 && !ballCountdownStarted) {
    if (ballSoloTimer) clearTimeout(ballSoloTimer);
    ballSoloTimer = setTimeout(ballRefundSoloBet, BALL_SOLO_TIMEOUT_MS);
  }

  if (ballCountdownStarted && ballPhase === 'betting') {
    const remainMs = ballBettingEndTs - Date.now();
    if (remainMs > 0 && remainMs <= 3000 && remainMs >= 1000) {
      // Anti-snipe: a bet landing in the true last-second danger zone
      // (1-3s left) gets a flat reset to 10s remaining, no matter how
      // small the bet — the proportional extension below already covers
      // bigger/earlier late bets in the wider 20s window, but a small
      // bet placed with only 1-3s left could otherwise still sneak in
      // with almost no reaction time for everyone else.
      ballBettingEndTs = Date.now() + 10000;
    } else {
      const NEAR_END_MS = 20000;
      if (remainMs > 0 && remainMs <= NEAR_END_MS) {
        const pot = ballPotTotal();
        const frac = pot > 0 ? amount/pot : 0;
        const baseExtensionSec = Math.max(0, Math.min(10, 11.25*frac - 0.125));
        const remainSec = remainMs/1000;
        const decay = Math.max(0, 1 - 0.05*remainSec);
        const extensionSec = baseExtensionSec * decay;
        if (extensionSec > 0) ballBettingEndTs += extensionSec*1000;
      }
    }
  }

  ballScheduleTransition();
  // Zones recompute on EVERY bet (not just once when betting closes) —
  // "при ставке: игрок получает зону в зависимости от его доли в банке"
  // means this should be visible live as people bet, the same way Wheel's
  // pie slices update live.
  ballSites = ballAssignZones();
  broadcast({
    type: 'ball_bet_update', bets: ballBetsList(), bettingEndTs: ballBettingEndTs,
    countdownStarted: ballCountdownStarted, sites: ballSites
  });
}

// ---------------------------------------------------------------------------
// Continuous power (Laguerre) diagram — NOT a grid. Each bettor is a "site"
// (x, y, w) somewhere in the 0..100 field; a point p belongs to whichever
// site minimizes (dist(p,site)^2 - site.w). Because that comparison is
// linear in p, the boundary between any two sites is a genuine straight
// line (their bisector) — so every territory is an exact convex polygon
// with perfectly smooth diagonal edges, no pixel staircase at any zoom
// level, unlike the previous 64x64 grid-cell version (which was smoother
// than the original 10x10 but still fundamentally a rasterized grid up
// close). Both server and client run this exact same math on the exact
// same site data (server resolves the weights once per bet and broadcasts
// them; the client only has to redo the cheap clipping pass to render).
// ---------------------------------------------------------------------------
function ballClipPolygon(poly, a, b, c){
  const out = [];
  const n = poly.length;
  for(let i=0;i<n;i++){
    const cur = poly[i], nxt = poly[(i+1)%n];
    const dCur = a*cur[0]+b*cur[1]-c, dNxt = a*nxt[0]+b*nxt[1]-c;
    const curIn = dCur <= 0, nxtIn = dNxt <= 0;
    if(curIn) out.push(cur);
    if(curIn !== nxtIn){
      const t = dCur/(dCur-dNxt);
      out.push([cur[0]+t*(nxt[0]-cur[0]), cur[1]+t*(nxt[1]-cur[1])]);
    }
  }
  return out;
}
function ballPolygonArea(poly){
  let a = 0;
  for(let i=0;i<poly.length;i++){
    const [x1,y1] = poly[i], [x2,y2] = poly[(i+1)%poly.length];
    a += x1*y2 - x2*y1;
  }
  return Math.abs(a)/2;
}
function ballBisector(si, sj){
  const a = 2*(sj.x - si.x);
  const b = 2*(sj.y - si.y);
  const c = (sj.x*sj.x + sj.y*sj.y - sj.w) - (si.x*si.x + si.y*si.y - si.w);
  return [a,b,c];
}
function ballComputeDiagram(sites){
  const square = [[0,0],[BALL_FIELD,0],[BALL_FIELD,BALL_FIELD],[0,BALL_FIELD]];
  return sites.map((si) => {
    let poly = square;
    for(const sj of sites){
      if(sj === si) continue;
      const [a,b,c] = ballBisector(si, sj);
      poly = ballClipPolygon(poly, a, b, c);
      if(poly.length === 0) break;
    }
    return poly;
  });
}

// Picks M well-spread site points — cheap farthest-candidate ("blue-noise-ish")
// sampling: for each new site, try a handful of random candidates and keep
// whichever is farthest from every site already placed. Good separation means
// the weight-fitting loop below doesn't start from badly overlapping sites.
function ballGenerateSites(M){
  const margin = 8, span = BALL_FIELD - margin*2;
  const pts = [];
  const tries = 30;
  for(let i=0; i<M; i++){
    if(pts.length === 0){
      pts.push({ x: margin+Math.random()*span, y: margin+Math.random()*span });
      continue;
    }
    let best = null, bestD = -1;
    for(let t=0; t<tries; t++){
      const cand = { x: margin+Math.random()*span, y: margin+Math.random()*span };
      let dmin = Infinity;
      for(const p of pts){
        const dx = cand.x-p.x, dy = cand.y-p.y;
        dmin = Math.min(dmin, dx*dx+dy*dy);
      }
      if(dmin > bestD){ bestD = dmin; best = cand; }
    }
    pts.push(best);
  }
  return pts;
}

// Iteratively nudges each site's weight until its polygon's area matches
// its target share of the field. Straight-line boundaries are kept at
// every step — only the weights move, never the geometry rule. Tuning
// validated up to 25 simultaneous bettors (see the mockup's
// test_diagram2.js): naive zero-init + fixed damping degenerates badly
// past ~10 players (some sites collapse to zero area and never recover).
// Fixed by (a) seeding weights at a sane initial scale instead of 0,
// (b) giving collapsed cells a fixed rescue boost instead of the
// meaningless zero-gradient proportional term, and (c) cooling the
// damping factor over the run so it settles instead of oscillating.
function ballFitWeights(sites, iterations=300){
  const targetTotal = BALL_FIELD*BALL_FIELD;
  sites.forEach(s => { s.w = s.share*targetTotal*0.5; });
  let damping = 0.5;
  for(let iter=0; iter<iterations; iter++){
    const polys = ballComputeDiagram(sites);
    for(let i=0;i<sites.length;i++){
      const targetArea = sites[i].share * targetTotal;
      const actualArea = ballPolygonArea(polys[i]);
      if(actualArea < 1e-6){
        sites[i].w += targetArea * 0.15;
      } else {
        sites[i].w += (targetArea - actualArea) * damping;
      }
    }
    damping *= 0.995;
  }
  return sites;
}

function ballAssignZones(){
  const M = ballBets.length;
  if(M === 0) return [];
  const pot = ballPotTotal();
  const pts = ballGenerateSites(M);
  const sites = ballBets.map((b,i) => ({
    x: pts[i].x, y: pts[i].y, w: 0,
    share: pot>0 ? b.amount/pot : 1/M
  }));
  if(M > 1) ballFitWeights(sites, 300);
  return sites;
}

function ballPowerDistance(site, x, y){
  return (x-site.x)*(x-site.x) + (y-site.y)*(y-site.y) - site.w;
}

// "Where the greater part of the ball is" — sample several points across
// the ball's circular footprint (not just its center) and tally which
// site wins each sample by power-distance (the exact same rule that
// DEFINES the diagram's own boundaries, so there's no separate numerical
// edge case where the ball can land exactly on a boundary line and get
// stuck undetermined — a real point-in-polygon edge-test can and does hit
// that ambiguity, power-distance argmin never does).
function ballDetermineWinnerIndex(){
  if(!ballSites.length) return -1;
  const samples = [[0,0],[0.6,0],[-0.6,0],[0,0.6],[0,-0.6],[0.42,0.42],[-0.42,0.42],[0.42,-0.42],[-0.42,-0.42]];
  const tally = new Array(ballSites.length).fill(0);
  for(const [dx,dy] of samples){
    const px = ball.x + dx*BALL_RADIUS, py = ball.y + dy*BALL_RADIUS;
    let best = 0, bestD = Infinity;
    ballSites.forEach((s,i) => { const d = ballPowerDistance(s,px,py); if(d<bestD){ bestD=d; best=i; } });
    tally[best]++;
  }
  let best = 0, bestCount = -1;
  tally.forEach((c,i) => { if(c>bestCount){ bestCount=c; best=i; } });
  return best;
}

function ballStartRound(){
  const pot = ballPotTotal();
  if (pot <= 0 || ballBets.length < 1) { ballStartBettingRound(); return; }
  ballPhase = 'arming';
  // Reuse whatever zone layout was already computed (and shown to
  // players) from the last bet — recomputing fresh here would silently
  // reshuffle everyone's zone into a different shape right as the ball
  // appears, which would look broken/untrustworthy ("that wasn't my zone
  // a second ago"). Only falls back to a fresh compute in the edge case
  // it's somehow still empty.
  if (!ballSites.length) ballSites = ballAssignZones();

  const startX = 20 + Math.random()*60, startY = 20 + Math.random()*60;
  const angleDeg = Math.random()*360;
  ball = { x: startX, y: startY, vx: 0, vy: 0 };

  broadcast({
    type: 'ball_zones', bets: ballBetsList(), sites: ballSites,
    ballStart: { x: startX, y: startY }, arrowAngleDeg: angleDeg, spinMs: BALL_ARROW_SPIN_MS
  });

  setTimeout(() => ballLaunch(angleDeg), BALL_ARROW_SPIN_MS);
}

function ballLaunch(angleDeg){
  if (ballPhase !== 'arming') return;
  ballPhase = 'rolling';
  const rad = angleDeg * Math.PI/180;
  ball.vx = Math.cos(rad) * BALL_SPEED;
  ball.vy = Math.sin(rad) * BALL_SPEED;

  if (ballTickTimer) clearInterval(ballTickTimer);
  ballTickTimer = setInterval(() => {
    ball.x += ball.vx; ball.y += ball.vy;
    if (ball.x - BALL_RADIUS < 0) { ball.x = BALL_RADIUS; ball.vx = -ball.vx; }
    if (ball.x + BALL_RADIUS > 100) { ball.x = 100 - BALL_RADIUS; ball.vx = -ball.vx; }
    if (ball.y - BALL_RADIUS < 0) { ball.y = BALL_RADIUS; ball.vy = -ball.vy; }
    if (ball.y + BALL_RADIUS > 100) { ball.y = 100 - BALL_RADIUS; ball.vy = -ball.vy; }
    ball.vx *= BALL_FRICTION; ball.vy *= BALL_FRICTION;
    broadcast({
      type: 'ball_tick',
      x: Math.round(ball.x*100)/100, y: Math.round(ball.y*100)/100,
      // Velocity is now included so the client can run its own local physics
      // simulation between ticks instead of only ever knowing sparse points —
      // see the client-side ballSim* code for why.
      vx: Math.round(ball.vx*1000)/1000, vy: Math.round(ball.vy*1000)/1000
    });
    const speed = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
    if (speed < BALL_STOP_SPEED) {
      clearInterval(ballTickTimer); ballTickTimer = null;
      ballFinishRound();
    }
  }, BALL_TICK_MS);
}

async function ballFinishRound(){
  const idx = ballDetermineWinnerIndex();
  const winnerBet = idx >= 0 ? ballBets[idx] : null;
  const pot = ballPotTotal();
  if (winnerBet && users[winnerBet.key]) {
    users[winnerBet.key].balance += pot;
    recordEarnings(winnerBet.username, pot - winnerBet.amount);
    await saveUsers();
    const winnerWs = ballSocketsByUser[winnerBet.key];
    if (winnerWs) sendTo(winnerWs, { type: 'balance', balance: users[winnerBet.key].balance });
  }
  pendingBallBets = {}; // round fully settled — nothing left unresolved to refund
  await saveGameState();

  if (winnerBet) {
    const chancePct = pot > 0 ? (winnerBet.amount/pot*100) : 0;
    ballHistory.unshift({ username: winnerBet.username, amount: pot, color: winnerBet.color, chancePct });
    ballHistory = ballHistory.slice(0, 10);
    ballBiggestWinEnsureDay();
    if (!ballBiggestWin || pot > ballBiggestWin.amount) {
      ballBiggestWin = { username: winnerBet.username, amount: pot, color: winnerBet.color, chancePct };
    }
    broadcast({
      type: 'ball_result',
      winner: { username: winnerBet.username, color: winnerBet.color, amount: winnerBet.amount, pot, chancePct },
      history: ballHistory, biggestWin: ballBiggestWin
    });
  }

  setTimeout(ballStartBettingRound, 4800);
}


// ---------------------------------------------------------------------------
// FFA ARENA ("FFA Арена") — betting works the same as Ball of Fate (open
// bets, pot grows, countdown extends on late/big bets), but the round
// itself is resolved by an actual melee-combat physics simulation instead
// of a single random pick. Every bettor becomes a ball in a 480x480 arena:
//
//   - radius is INVERSE to bet share: the bigger the bet, the SMALLER the
//     ball (small-ball players get a damage/HP/weapon-length bonus based on
//     their bet rank, and switch to a hammer instead of a sword once their
//     share crosses HAMMER_PCT_THRESHOLD — high-roller glass cannons vs.
//     low-roller tanky bruisers)
//   - every ball has a sword or hammer spinning around it that deals real
//     HP damage on contact
//   - green/blue/red powerups spawn over time (heal / weapon speed / sword
//     length)
//   - balls bounce off walls and each other with real elastic collisions,
//     weapons are separate hitboxes that rotate and land damage
//
// The server only steps this simulation forward and reports it tick by
// tick — it never picks a winner directly. The last ball standing (after
// real HP-based eliminations from actual weapon contact, driven by actual
// collision trajectories) takes the whole pot.
// ---------------------------------------------------------------------------
const FFA_MIN_BET = 1;
const FFA_BETTING_MS = 15000;
const FFA_ARM_MS = 2500;            // pause between "sizes/weapons assigned" and "fight starts"
const FFA_MAX_ADDS = 5;
const FFA_SOLO_TIMEOUT_MS = 7 * 60 * 1000; // no 2nd bettor within this long -> auto-refund and reset

// --- arena / combat constants, ported 1:1 from the reference FFA physics ---
const FFA_W = 480, FFA_H = 480;
const FFA_PCT_FLOOR = 8, FFA_PCT_CEIL = 82;
const FFA_BALL_R_MIN = 11, FFA_BALL_R_MAX = 26;
const FFA_HAMMER_PCT_THRESHOLD = 70;
const FFA_SWORD_INITIAL_SPEED = 0.09;   // rad per 1/60s-equivalent physics step
const FFA_SWORD_MAX_SPEED = 0.4;
const FFA_SWORD_BASE_LEN = 40;
const FFA_SWORD_BASE_DMG = 5;
const FFA_HAMMER_BASE_DMG = 3;
const FFA_HAMMER_DMG_MULT_STEP = 1.05;
const FFA_HP_BASE = 100;
const FFA_SWORD_HALF_WIDTH = 5;
const FFA_HAMMER_HALF_WIDTH = 9;
const FFA_HIT_COOLDOWN_STEPS = 12;
const FFA_MAX_POWERUPS = 7;
const FFA_POWERUP_R = 11;
const FFA_MAX_SPEED = 6;
// One "sim step" == one 1/60s-equivalent physics frame from the reference
// implementation (weapon rotation speed, hit cooldowns etc. are all tuned
// to that unit). We run FFA_SUBSTEPS_PER_TICK of them per broadcast tick,
// so the simulation itself runs at the original fidelity while the network
// only gets an update every FFA_TICK_MS.
const FFA_SUBSTEP_MS = 1000/60;
const FFA_SUBSTEPS_PER_TICK = 3;
const FFA_TICK_MS = Math.round(FFA_SUBSTEP_MS * FFA_SUBSTEPS_PER_TICK); // ~50ms

let ffaPhase = 'betting'; // 'betting' | 'arming' | 'combat'
let ffaBets = []; // { key, username, amount, color, avatarUrl } — used while phase is 'betting'
let ffaColorCursor = 0;
let ffaCountdownStarted = false;
let ffaBettingEndTs = 0;
let ffaPhaseTimer = null;
let ffaArmTimer = null;
let ffaTickTimer = null;
let ffaSoloTimer = null;
let ffaSimStep = 0;         // counts substeps within the current combat round, for powerup spawn cadence
let ffaPlayers = [];        // full combat state once phase is 'arming'/'combat' — see ffaStartRound()
let ffaPowerups = [];
let ffaHistory = [];
let ffaBiggestWin = null;
let ffaBiggestWinDay = null;
function ffaBiggestWinEnsureDay() {
  const today = mskDateString(Date.now());
  if (ffaBiggestWinDay !== today) { ffaBiggestWinDay = today; ffaBiggestWin = null; }
}
let pendingFfaBets = {};
let ffaSocketsByUser = {};
let ffaAddCounts = {}; // key -> how many times they've added this round

function ffaPotTotal(){ return ffaBets.reduce((s,b)=>s+b.amount, 0); }
function ffaNextColor(){ const c = WHEEL_SLICE_COLORS[ffaColorCursor % WHEEL_SLICE_COLORS.length]; ffaColorCursor++; return c; }
function ffaBetsList(){
  return ffaBets.map(b => ({
    username: b.username, amount: b.amount, color: b.color, avatarUrl: b.avatarUrl || null,
    x: b.x, y: b.y, r: b.r
  }));
}

function ffaRadiusFromPct(pct){
  const t = Math.max(0, Math.min(1, (pct - FFA_PCT_FLOOR) / (FFA_PCT_CEIL - FFA_PCT_FLOOR)));
  const eased = Math.sqrt(t);
  return FFA_BALL_R_MAX - eased * (FFA_BALL_R_MAX - FFA_BALL_R_MIN);
}

// Finds one spawn point kept apart from every ball already placed on the
// arena (by at least the sum of radii, plus a margin) — used ONLY for a
// bettor's very first bet this round. Falls back to the last attempt if it
// can't find a fully clean spot in time (extremely unlikely at <=8 balls).
function ffaFindSpawnPoint(r, others, margin){
  margin = margin || 60;
  let best = null;
  for (let attempt = 0; attempt < 60; attempt++) {
    const x = margin + Math.random() * (FFA_W - margin*2);
    const y = margin + Math.random() * (FFA_H - margin*2);
    let ok = true;
    for (let j = 0; j < others.length; j++) {
      const dx = x - others[j].x, dy = y - others[j].y;
      const minDist = r + others[j].r + 4;
      if (dx*dx + dy*dy < minDist*minDist) { ok = false; break; }
    }
    if (ok) { best = [x, y]; break; }
    if (!best) best = [x, y];
  }
  return best;
}

// Just like the reference FFA: every bettor's ball is placed on the arena
// the moment they bet and STAYS THERE, unmoving, through the rest of
// betting/countdown — nothing gets rebuilt or re-scattered when combat
// starts, only velocity gets added then. So position/radius have to be
// live here, during betting, not computed later in ffaStartRound.
// `newKey` (if any) is the bettor who just placed their FIRST bet this
// round — everyone else keeps their existing x/y (only their radius may
// change as the pot shifts); the newcomer gets a fresh spawn point kept
// clear of everyone already on the arena.
function ffaRecomputeBettingLayout(newKey){
  const pot = ffaPotTotal();
  const pctOf = (bet) => pot > 0 ? Math.max(FFA_PCT_FLOOR, Math.min(FFA_PCT_CEIL, (bet/pot)*100)) : FFA_PCT_FLOOR;
  ffaBets.forEach(b => { b.pct = pctOf(b.amount); b.r = ffaRadiusFromPct(b.pct); });
  if (newKey) {
    const newBet = ffaBets.find(b => b.key === newKey);
    const others = ffaBets.filter(b => b.key !== newKey);
    const pt = ffaFindSpawnPoint(newBet.r, others);
    newBet.x = pt[0]; newBet.y = pt[1];
  }
}

function ffaScheduleTransition(){
  if (ffaPhaseTimer) { clearTimeout(ffaPhaseTimer); ffaPhaseTimer = null; }
  if (ffaPhase !== 'betting' || !ffaCountdownStarted) return;
  const delay = Math.max(0, ffaBettingEndTs - Date.now());
  ffaPhaseTimer = setTimeout(() => { if (ffaPhase === 'betting') ffaStartRound(); }, delay);
}

function ffaStartBettingRound(){
  ffaPhase = 'betting';
  ffaBets = [];
  ffaColorCursor = 0;
  ffaCountdownStarted = false;
  ffaBettingEndTs = 0;
  ffaPlayers = [];
  ffaPowerups = [];
  ffaSimStep = 0;
  ffaAddCounts = {};
  if (ffaPhaseTimer) { clearTimeout(ffaPhaseTimer); ffaPhaseTimer = null; }
  if (ffaArmTimer) { clearTimeout(ffaArmTimer); ffaArmTimer = null; }
  if (ffaTickTimer) { clearInterval(ffaTickTimer); ffaTickTimer = null; }
  if (ffaSoloTimer) { clearTimeout(ffaSoloTimer); ffaSoloTimer = null; }
  ffaBiggestWinEnsureDay();
  broadcast({ type: 'ffa_round_start', bets: ffaBetsList(), history: ffaHistory, biggestWin: ffaBiggestWin });
}

async function ffaRefundSoloBet(){
  if (ffaPhase !== 'betting' || ffaCountdownStarted || ffaBets.length !== 1) return;
  const b = ffaBets[0];
  if (users[b.key]) {
    users[b.key].balance += b.amount;
    await saveUsers();
    const soloWs = ffaSocketsByUser[b.key];
    if (soloWs) {
      sendTo(soloWs, { type: 'balance', balance: users[b.key].balance });
      sendTo(soloWs, { type: 'ffa_solo_refund', amount: b.amount });
    }
  }
  delete pendingFfaBets[b.key];
  await saveGameState();
  ffaStartBettingRound();
}

function ffaPlaceBet(key, username, amount){
  const existing = ffaBets.find(b => b.key === key);
  const isNewBettor = !existing;
  if (existing) { existing.amount = Math.round((existing.amount + amount)*100)/100; }
  else { ffaBets.push({ key, username, amount, color: ffaNextColor(), avatarUrl: (users[key] && users[key].avatarUrl) || null, x: 0, y: 0, r: FFA_BALL_R_MIN, pct: FFA_PCT_FLOOR }); }

  // Real position+radius, assigned now and never touched again until
  // combat actually starts moving them — see ffaRecomputeBettingLayout().
  ffaRecomputeBettingLayout(isNewBettor ? key : null);

  if (!ffaCountdownStarted && ffaBets.length >= 2 && ffaPhase === 'betting') {
    ffaCountdownStarted = true;
    ffaBettingEndTs = Date.now() + FFA_BETTING_MS;
    if (ffaSoloTimer) { clearTimeout(ffaSoloTimer); ffaSoloTimer = null; }
  } else if (ffaBets.length === 1 && !ffaCountdownStarted) {
    if (ffaSoloTimer) clearTimeout(ffaSoloTimer);
    ffaSoloTimer = setTimeout(ffaRefundSoloBet, FFA_SOLO_TIMEOUT_MS);
  }

  if (ffaCountdownStarted && ffaPhase === 'betting') {
    const remainMs = ffaBettingEndTs - Date.now();
    if (remainMs > 0 && remainMs <= 3000 && remainMs >= 1000) {
      ffaBettingEndTs = Date.now() + 10000;
    } else {
      const NEAR_END_MS = 20000;
      if (remainMs > 0 && remainMs <= NEAR_END_MS) {
        const pot = ffaPotTotal();
        const frac = pot > 0 ? amount/pot : 0;
        const baseExtensionSec = Math.max(0, Math.min(10, 11.25*frac - 0.125));
        const remainSec = remainMs/1000;
        const decay = Math.max(0, 1 - 0.05*remainSec);
        const extensionSec = baseExtensionSec * decay;
        if (extensionSec > 0) ffaBettingEndTs += extensionSec*1000;
      }
    }
  }

  ffaScheduleTransition();
  broadcast({
    type: 'ffa_bet_update', bets: ffaBetsList(), bettingEndTs: ffaBettingEndTs,
    countdownStarted: ffaCountdownStarted
  });
}

function ffaStartRound(){
  const pot = ffaPotTotal();
  if (pot <= 0 || ffaBets.length < 2) { ffaStartBettingRound(); return; }
  ffaPhase = 'arming';

  // Positions/radii were already fixed live during betting (see
  // ffaRecomputeBettingLayout) — arming just attaches weapon/HP/mass to
  // the SAME spot each ball has been sitting at. Nothing is re-scattered
  // here, so there's no jump/teleport going into the fight.
  ffaPlayers = ffaBets.map(b => {
    const pct = b.pct;
    // +5% damage/HP/sword-length bonus for every other bettor in this round
    // whose bet is smaller than this one's — a small bet can still end up
    // with zero bonus, a whale stacks bonus off everyone below them.
    const smallerCount = ffaBets.filter(o => o.amount < b.amount).length;
    const betDmgBonusPct = smallerCount * 5;
    const weaponType = pct >= FFA_HAMMER_PCT_THRESHOLD ? 'hammer' : 'sword';
    const weaponLen = weaponType === 'sword'
      ? FFA_SWORD_BASE_LEN * (1 + betDmgBonusPct/100)
      : 26 + pct*0.35;
    const maxHp = FFA_HP_BASE * (1 + betDmgBonusPct/100);
    const mass = Math.max(1, 100 - pct)/10 + 1;
    return {
      key: b.key, username: b.username, amount: b.amount, color: b.color, avatarUrl: b.avatarUrl,
      pct, x: b.x, y: b.y, vx: 0, vy: 0, r: b.r, mass,
      hp: maxHp, maxHp, alive: true,
      weaponType, weaponLen, weaponAngle: Math.random()*Math.PI*2,
      weaponSpeed: FFA_SWORD_INITIAL_SPEED, hammerDmgMult: 1,
      hitCooldown: 0, betDmgBonusPct, minSpeed: 3
    };
  });
  ffaPowerups = [];
  ffaSimStep = 0;

  broadcast({
    type: 'ffa_arm',
    players: ffaPlayers.map(ffaPublicPlayer),
    armMs: FFA_ARM_MS
  });

  ffaArmTimer = setTimeout(ffaBeginCombat, FFA_ARM_MS);
}

function ffaPublicPlayer(p){
  return {
    username: p.username, color: p.color, amount: p.amount, avatarUrl: p.avatarUrl,
    x: Math.round(p.x*100)/100, y: Math.round(p.y*100)/100, r: Math.round(p.r*100)/100,
    // vx/vy included (same idea as ball_tick) so the client can dead-reckon
    // each ball's position between ticks instead of only ever knowing
    // sparse points — see the client-side ffaSim* code.
    vx: Math.round((p.vx||0)*1000)/1000, vy: Math.round((p.vy||0)*1000)/1000,
    hp: Math.round(p.hp*10)/10, maxHp: Math.round(p.maxHp*10)/10, alive: p.alive,
    weaponType: p.weaponType, weaponAngle: Math.round(p.weaponAngle*1000)/1000,
    weaponSpeed: Math.round((p.weaponSpeed||0)*10000)/10000,
    weaponLen: Math.round(p.weaponLen*10)/10
  };
}

function ffaAliveCount(){ return ffaPlayers.reduce((n,p) => n + (p.alive ? 1 : 0), 0); }

function ffaBeginCombat(){
  if (ffaPhase !== 'arming') return;
  ffaPhase = 'combat';
  ffaPlayers.forEach(p => {
    const a = Math.random()*Math.PI*2;
    const speed = 3 + Math.random()*1.2;
    p.vx = Math.cos(a)*speed; p.vy = Math.sin(a)*speed;
    p.minSpeed = speed;
  });
  if (ffaTickTimer) clearInterval(ffaTickTimer);
  ffaTickTimer = setInterval(ffaTick, FFA_TICK_MS);
}

function ffaClampWeaponSpeed(p){
  const dir = p.weaponSpeed >= 0 ? 1 : -1;
  const abs = Math.max(FFA_SWORD_INITIAL_SPEED, Math.min(FFA_SWORD_MAX_SPEED, Math.abs(p.weaponSpeed)));
  p.weaponSpeed = dir*abs;
}

function ffaSpawnPowerup(){
  if (ffaPowerups.length >= FFA_MAX_POWERUPS) return;
  const rnd = Math.random();
  const type = rnd < 0.20 ? 'green' : rnd < 0.70 ? 'blue' : 'red';
  ffaPowerups.push({ x: 55 + Math.random()*(FFA_W-110), y: 55 + Math.random()*(FFA_H-110), type, r: FFA_POWERUP_R });
}

// Distance from a point to the weapon's line segment (handle end -> tip),
// used as the weapon's hitbox against an enemy's circle — the same
// geometry the reference implementation gets via a rotated rectangle body.
function ffaPointToSegmentDist(px, py, ax, ay, bx, by){
  const abx = bx-ax, aby = by-ay;
  const apx = px-ax, apy = py-ay;
  const abLen2 = abx*abx + aby*aby;
  let t = abLen2 > 0 ? (apx*abx + apy*aby)/abLen2 : 0;
  t = Math.max(0, Math.min(1, t));
  const cx = ax + abx*t, cy = ay + aby*t;
  return Math.hypot(px-cx, py-cy);
}

// One 1/60s-equivalent physics step — movement, wall bounce, ball-ball
// elastic collision, weapon rotation + weapon-vs-enemy hit detection,
// powerup pickup. Mirrors the reference FFA's per-frame update() 1:1
// (just without Matter.js underneath — the collision math is the real
// elastic-collision formula so it behaves the same way).
function ffaSubStep(eliminatedOut, bouncesOut, powerupsOut){
  ffaSimStep++;
  if (ffaSimStep === 60 || ffaSimStep % 180 === 0) ffaSpawnPowerup();

  const alive = ffaPlayers.filter(p => p.alive);

  alive.forEach(p => {
    p.weaponAngle += p.weaponSpeed;
    if (p.hitCooldown > 0) p.hitCooldown--;
    p.x += p.vx; p.y += p.vy;
    if (p.x - p.r < 0) { p.x = p.r; p.vx = Math.abs(p.vx); bouncesOut.push(Math.hypot(p.vx,p.vy)/3.5); }
    if (p.x + p.r > FFA_W) { p.x = FFA_W - p.r; p.vx = -Math.abs(p.vx); bouncesOut.push(Math.hypot(p.vx,p.vy)/3.5); }
    if (p.y - p.r < 0) { p.y = p.r; p.vy = Math.abs(p.vy); bouncesOut.push(Math.hypot(p.vx,p.vy)/3.5); }
    if (p.y + p.r > FFA_H) { p.y = FFA_H - p.r; p.vy = -Math.abs(p.vy); bouncesOut.push(Math.hypot(p.vx,p.vy)/3.5); }
  });

  // ball-vs-ball real elastic collision (mass-weighted, restitution 1)
  for (let i = 0; i < alive.length; i++) {
    const a = alive[i];
    for (let j = i+1; j < alive.length; j++) {
      const b = alive[j];
      const dx = b.x-a.x, dy = b.y-a.y;
      const dist = Math.hypot(dx,dy) || 0.0001;
      const minDist = a.r + b.r;
      if (dist >= minDist) continue;
      const nx = dx/dist, ny = dy/dist;
      const avn = a.vx*nx + a.vy*ny, bvn = b.vx*nx + b.vy*ny;
      // same "ball hits ball" thud cue as the reference FFA's collisionStart
      // handler — strength derived from the pair's relative speed.
      const relSpeed = Math.hypot(a.vx-b.vx, a.vy-b.vy);
      bouncesOut.push(relSpeed/3.5);
      const m1 = a.mass, m2 = b.mass;
      const avn2 = (avn*(m1-m2) + 2*m2*bvn) / (m1+m2);
      const bvn2 = (bvn*(m2-m1) + 2*m1*avn) / (m1+m2);
      a.vx += (avn2-avn)*nx; a.vy += (avn2-avn)*ny;
      b.vx += (bvn2-bvn)*nx; b.vy += (bvn2-bvn)*ny;
      const overlap = minDist - dist;
      a.x -= nx*overlap/2; a.y -= ny*overlap/2;
      b.x += nx*overlap/2; b.y += ny*overlap/2;
    }
  }

  // speed floor/ceiling, same as ensureMinSpeed/clampSpeed in the source
  alive.forEach(p => {
    const spd = Math.hypot(p.vx, p.vy);
    if (spd < p.minSpeed && spd > 0.0001) { const s = p.minSpeed/spd; p.vx *= s; p.vy *= s; }
    else if (spd <= 0.0001) { p.vx = p.minSpeed; p.vy = p.minSpeed*0.5; }
    else if (spd > FFA_MAX_SPEED) { const s = FFA_MAX_SPEED/spd; p.vx *= s; p.vy *= s; }
  });

  // weapon-vs-enemy hit detection (no hit sfx here — the reference FFA
  // explicitly disables sfxHit() "by request", so we don't emit a hit event)
  alive.forEach(owner => {
    if (!owner.alive || owner.hitCooldown > 0) return;
    const ux = Math.cos(owner.weaponAngle), uy = Math.sin(owner.weaponAngle);
    const ax = owner.x + ux*owner.r, ay = owner.y + uy*owner.r;
    const bx = owner.x + ux*(owner.r + owner.weaponLen), by = owner.y + uy*(owner.r + owner.weaponLen);
    const halfWidth = owner.weaponType === 'hammer' ? FFA_HAMMER_HALF_WIDTH : FFA_SWORD_HALF_WIDTH;
    alive.forEach(enemy => {
      if (enemy === owner || !enemy.alive || owner.hitCooldown > 0) return;
      const d = ffaPointToSegmentDist(enemy.x, enemy.y, ax, ay, bx, by);
      if (d > enemy.r + halfWidth) return;

      const baseDmg = owner.weaponType === 'hammer' ? FFA_HAMMER_BASE_DMG*owner.hammerDmgMult : FFA_SWORD_BASE_DMG;
      const dmg = owner.weaponType === 'hammer' ? baseDmg : baseDmg*(1 + owner.betDmgBonusPct/100);
      enemy.hp = Math.max(0, enemy.hp - Math.round(dmg*10)/10);
      owner.hitCooldown = FFA_HIT_COOLDOWN_STEPS;
      if (owner.weaponType === 'hammer') owner.hammerDmgMult *= FFA_HAMMER_DMG_MULT_STEP;
      owner.weaponSpeed = (owner.weaponSpeed >= 0 ? -1 : 1) * Math.abs(owner.weaponSpeed);

      if (enemy.hp <= 0 && enemy.alive) {
        enemy.alive = false;
        eliminatedOut.push(enemy.username);
      }
    });
  });

  // powerup pickup
  // Pickup hitbox is intentionally NOT tied to the player's current ball
  // radius (p.r) — that radius shrinks as a player's bet grows, which would
  // otherwise punish big bettors with a smaller pickup zone. Instead every
  // player gets the same pickup reach, fixed to the smallest ball size
  // (FFA_BALL_R_MIN, i.e. the size at the largest possible bet), so bonus
  // collection is fair regardless of stake.
  alive.forEach(p => {
    if (!p.alive) return;
    ffaPowerups = ffaPowerups.filter(pu => {
      if (Math.hypot(pu.x-p.x, pu.y-p.y) < FFA_BALL_R_MIN + pu.r) {
        if (pu.type === 'green') p.hp = Math.min(p.maxHp, p.hp + 15);
        else if (pu.type === 'blue') { p.weaponSpeed *= 1.3; ffaClampWeaponSpeed(p); }
        else p.weaponLen += 7;
        powerupsOut.push(pu.type);
        return false;
      }
      return true;
    });
  });
}

function ffaTick(){
  const eliminated = [];
  const bounces = [];
  const powerupsCollected = [];
  for (let s = 0; s < FFA_SUBSTEPS_PER_TICK; s++) {
    if (ffaAliveCount() <= 1) break;
    ffaSubStep(eliminated, bounces, powerupsCollected);
  }

  broadcast({
    type: 'ffa_tick',
    players: ffaPlayers.map(ffaPublicPlayer),
    powerups: ffaPowerups,
    bounces, powerupsCollected,
    eliminated
  });

  if (ffaAliveCount() <= 1) {
    clearInterval(ffaTickTimer); ffaTickTimer = null;
    ffaFinishRound();
  }
}

async function ffaFinishRound(){
  const winner = ffaPlayers.find(p => p.alive) || ffaPlayers[0];
  const pot = ffaPotTotal();
  if (winner && users[winner.key]) {
    users[winner.key].balance += pot;
    recordEarnings(winner.username, pot - winner.amount);
    await saveUsers();
    const winnerWs = ffaSocketsByUser[winner.key];
    if (winnerWs) sendTo(winnerWs, { type: 'balance', balance: users[winner.key].balance });
  }
  pendingFfaBets = {};
  await saveGameState();

  if (winner) {
    // Same "chance" metric as Wheel/Ball of Fate: the winner's stake as a share of the pot —
    // not literally their combat win probability (that also depends on ball size/weapon/HP),
    // but it's the consistent number already shown pre-round in ffaRenderPlayers' % column.
    const chancePct = pot > 0 ? (winner.amount/pot*100) : 0;
    ffaHistory.unshift({ username: winner.username, amount: pot, color: winner.color, chancePct });
    ffaHistory = ffaHistory.slice(0, 10);
    ffaBiggestWinEnsureDay();
    if (!ffaBiggestWin || pot > ffaBiggestWin.amount) {
      ffaBiggestWin = { username: winner.username, amount: pot, color: winner.color, chancePct };
    }
    broadcast({
      type: 'ffa_result',
      winner: { username: winner.username, color: winner.color, amount: winner.amount, pot, chancePct },
      history: ffaHistory, biggestWin: ffaBiggestWin
    });
  }

  setTimeout(ffaStartBettingRound, 4800);
}



function genCrashPoint() {
  const r = Math.random();
  if (r < HOUSE_EDGE) return 1.00;
  let cp = (1 - HOUSE_EDGE) / (1 - r);
  cp = Math.floor(cp * 100) / 100;
  return Math.min(MAX_MULTIPLIER, Math.max(1.00, cp));
}
function timeForMultiplier(target) {
  const lnT = Math.log(target);
  const a = GROWTH_K2, b = GROWTH_K1, c = -lnT;
  return (-b + Math.sqrt(b * b - 4 * a * c)) / (2 * a);
}
function multiplierAtTime(t) {
  return Math.min(MAX_MULTIPLIER, Math.exp(GROWTH_K1 * t + GROWTH_K2 * t * t));
}
function mskDateString(ts) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Moscow', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(ts));
}
function mskNextMidnightISO() {
  // find next 00:00 Europe/Moscow as an ISO timestamp
  const now = new Date();
  const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Moscow', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
  const parts = Object.fromEntries(fmt.formatToParts(now).map(p => [p.type, p.value]));
  const mskNow = new Date(`${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}Z`);
  const nextMidnightMsk = new Date(Date.UTC(mskNow.getUTCFullYear(), mskNow.getUTCMonth(), mskNow.getUTCDate() + 1, 0, 0, 0));
  const diffMs = nextMidnightMsk.getTime() - mskNow.getTime();
  return new Date(now.getTime() + diffMs).toISOString();
}

// ---------------------------------------------------------------------------
// MAIN CRASH BOTS — fake players that make the round feel populated. Each
// one independently has a 50% chance to sit in on any given round (rolled
// fresh every round, at the start of the betting window). Their stake is
// random between 0.1 and 2700.
//
// Each bot's win/lose fate is decided by its OWN independent roll, with its
// own BOT_HOUSE_EDGE — deliberately NOT by comparing against this round's
// shared crashPoint. Tying every bot to the one shared crashPoint would
// correlate all of them together (and with the real rocket): a round that
// happens to crash early would make every bot lose together, and a bot
// could never "win" past wherever this particular round's rocket stopped.
// An independent per-bot roll avoids both: a bot can cash out at ~1.5x
// while the real multiplier keeps climbing on for everyone else, and one
// round's early crash doesn't doom every bot in it.
//
// Bot entries live in the same `bets` object as real players, under a
// 'bot:<name>' key so they can never collide with a real username — but
// the `username` field (the only part ever sent to clients) is just the
// plain name, no prefix/suffix, so they render identically to a real
// player in the "players this round" list.
// ---------------------------------------------------------------------------
const BOT_NAMES = ['Geero', 'Bobik', 'Гандон', 'Kustik', 'Какашака', 'Лютый_чел', 'Veriti', 'Email', 'Ebati'];
const BOT_JOIN_CHANCE = 0.5;
const BOT_MIN_BET = 0.1;
const BOT_MAX_BET = 2700;
const BOT_HOUSE_EDGE = 0.015; // bots' own edge — independent of the real round's crashPoint/HOUSE_EDGE

function pickBotTargetMult() {
  // The exact same formula/shape genCrashPoint() uses for the REAL crash
  // point — a bot's target is nothing but a personal draw off
  // BOT_HOUSE_EDGE. No hand-picked median/offset/scale, no separate
  // win-probability roll bolted on afterward: this one draw IS the bot's
  // fate. r < edge mirrors the real "instant crash" case (1.5% of rounds
  // crash at 1.00x with no chance to cash) — the bot is simply doomed this
  // round, same as any real player would be.
  const r = Math.random();
  if (r < BOT_HOUSE_EDGE) return 1.00;
  return Math.round(((1 - BOT_HOUSE_EDGE) / (1 - r)) * 100) / 100;
}

// Bots used to all get inserted into `bets{}` synchronously, in one go, the
// instant the betting window opened — so every bot that was joining this
// round was already sitting in the player list on the very first tick,
// which reads as fake/robotic ("they all spawn at once"). Real players
// trickle in over the whole countdown, so bots should too: spawnBotBets()
// now only ROLLS which bots join (and when), and admitDueBots() — called
// on every 100ms tick during the betting window — actually inserts each
// one into `bets{}` once its randomly-chosen moment arrives.
let scheduledBots = [];

function spawnBotBets() {
  scheduledBots = [];
  for (const name of BOT_NAMES) {
    if (Math.random() >= BOT_JOIN_CHANCE) continue; // sits this round out
    const amount = Math.round((BOT_MIN_BET + Math.random() * (BOT_MAX_BET - BOT_MIN_BET)) * 100) / 100;
    const target = pickBotTargetMult(); // already IS the house-edge draw — no separate win roll
    scheduledBots.push({
      name, amount, target,
      joinAtTs: Date.now() + Math.random() * BETTING_MS // any moment during this round's countdown
    });
  }
}

function admitDueBots() {
  const now = Date.now();
  for (let i = scheduledBots.length - 1; i >= 0; i--) {
    const sb = scheduledBots[i];
    if (sb.joinAtTs > now) continue;
    bets['bot:' + sb.name] = {
      username: sb.name, amount: sb.amount, status: 'active', mult: null,
      isBot: true, botTarget: sb.target
    };
    scheduledBots.splice(i, 1);
  }
}

function resolveBotCashouts() {
  for (const key of Object.keys(bets)) {
    const b = bets[key];
    // botTarget already IS this bot's house-edge draw (see
    // pickBotTargetMult) — cash out once the live multiplier reaches it.
    // If this round's crashPoint lands short of it, the bot just busts
    // along with everyone else still active — no rescue, no special case.
    if (b.isBot && b.status === 'active' && currentMultiplier >= b.botTarget) {
      b.status = 'cashed';
      b.mult = b.botTarget;
    }
  }
}

// ---------------------------------------------------------------------------
// MAIN ROUND STATE (global, shared by all connected players)
// ---------------------------------------------------------------------------
let phase = 'waiting'; // waiting | running | crashed
let bettingEndTs = 0;
let roundStartTs = 0;
let crashPoint = 1;
let crashTimeSec = 0;
let currentMultiplier = 1;
let bets = {}; // key -> {username, amount, status:'active'|'cashed'|'busted', mult:number|null}
let history = [];
let pendingStairsBets = {}; // key -> amount staked, cleared once stairs_result comes back in

// ---------------------------------------------------------------------------
// ROULETTE — the server runs ONE real physics simulation per spin (random
// initial angular velocity + exponential friction decay — the same "real
// wheel" model as before), and only AFTER running it reads off which
// sector the wheel actually stopped on. That result is broadcast to every
// client together with the physics parameters (v0, tau, start angle,
// start timestamp) exactly once, at the moment the spin begins — every
// client then reproduces the identical deterministic motion locally from
// those numbers, so everyone watches the same spin land on the same
// sector without polling the server every frame (that polling is what
// caused the earlier jitter/lag). The betting countdown is likewise sent
// once (a single shared end-timestamp) and each client counts down to it
// locally; the live player list updates via one small event per bet
// placed, not a repeating full-list broadcast.
// ---------------------------------------------------------------------------
const ROULETTE_SECTORS = [
  {c:'green',n:0},{c:'red',n:1},{c:'black',n:2},{c:'red',n:3},{c:'yellow',n:4},
  {c:'red',n:5},{c:'black',n:6},{c:'red',n:7},{c:'black',n:8},{c:'red',n:9},
  {c:'yellow',n:10},{c:'red',n:11},{c:'black',n:12},{c:'red',n:13},{c:'black',n:14},
  {c:'red',n:15},{c:'yellow',n:16},{c:'red',n:17},{c:'black',n:18},{c:'red',n:19}
];
const ROULETTE_MULT = { red: 2, black: 3, yellow: 5, green: 14 };
const ROULETTE_BETTING_MS = 10000;
const ROULETTE_MIN_BET = 1; // matches the client's own RLT_MIN_STAKE
const ROULETTE_VEND = 0.03; // рад/с — тот же порог "уже незаметно глазу", что и в клиентской формуле
const ROULETTE_IDLE_OMEGA = 0.35; // рад/с — медленное вращение колеса во время ожидания ставок (~18с на полный круг)
const ROULETTE_BOT_NAMES = ['Geero', 'Bobik', 'Kustik', 'Лютый_чел', 'Veriti', 'Email', 'Shurik', 'Nova_', 'Pixel'];
const ROULETTE_BOT_JOIN_CHANCE = 0.55;
const ROULETTE_BOT_MIN_BET = 10, ROULETTE_BOT_MAX_BET = 2500;
const ROULETTE_BET_COLORS = ['red', 'black', 'yellow', 'green'];

let rouletteSocketsByUser = {};
let roulettePhase = 'betting'; // betting | spinning
let rouletteBettingEndTs = 0;
let rouletteBettingStartTs = 0;  // точка отсчёта медленного вращения на ожидании — общая для всех клиентов
let rouletteRotation = 0;        // угол колеса на момент начала текущей фазы ожидания (баланс для медленного вращения)
let rouletteSpinStartTs = 0;
let rouletteSpinParams = null;   // {startRotation, v0, tau, spinDurationMs} — для клиентов, подключившихся во время спина
let rouletteWinIndex = 0;
let rouletteHistory = [];
let rouletteBets = {};           // username -> {username, color, amount} — текущий список раунда (боты + реальные)
let rouletteBotTimers = [];
let pendingRouletteBets = {};    // authed -> {color, amount} — реально списанные деньги, до resolve

function rouletteScheduleBots() {
  rouletteBotTimers.forEach(t => clearTimeout(t));
  rouletteBotTimers = [];
  for (const name of ROULETTE_BOT_NAMES) {
    if (Math.random() >= ROULETTE_BOT_JOIN_CHANCE) continue; // сидит этот раунд в стороне
    const delay = Math.random() * ROULETTE_BETTING_MS;
    const timer = setTimeout(() => {
      if (roulettePhase !== 'betting') return;
      const bet = {
        username: name,
        color: ROULETTE_BET_COLORS[Math.floor(Math.random() * ROULETTE_BET_COLORS.length)],
        amount: Math.round(ROULETTE_BOT_MIN_BET + Math.random() * (ROULETTE_BOT_MAX_BET - ROULETTE_BOT_MIN_BET))
      };
      rouletteBets[name] = bet;
      broadcast({ type: 'roulette_bet_added', bet });
    }, delay);
    rouletteBotTimers.push(timer);
  }
}
function rouletteStartBetting() {
  roulettePhase = 'betting';
  rouletteBets = {};
  rouletteSpinParams = null;
  rouletteBettingStartTs = Date.now();
  rouletteBettingEndTs = rouletteBettingStartTs + ROULETTE_BETTING_MS;
  rouletteScheduleBots();
  // rouletteRotation здесь — это угол, на котором колесо честно остановилось
  // в конце предыдущего спина (или 0 при самом первом запуске). Дальше, пока
  // идут ставки, оно не стоит на месте: см. ROULETTE_IDLE_OMEGA — каждый
  // клиент сам досчитывает его текущее положение от этой ОДНОЙ общей точки
  // отсчёта (restRotation + bettingStartTs), поэтому оно крутится одинаково
  // у всех, а не с разного случайного места на каждом экране.
  broadcast({
    type: 'roulette_phase', phase: 'betting',
    bettingEndTs: rouletteBettingEndTs, bettingStartTs: rouletteBettingStartTs,
    restRotation: rouletteRotation, idleOmega: ROULETTE_IDLE_OMEGA,
    history: rouletteHistory
  });
  setTimeout(rouletteStartSpin, ROULETTE_BETTING_MS);
}
function rouletteStartSpin() {
  roulettePhase = 'spinning';
  rouletteBotTimers.forEach(t => clearTimeout(t));
  rouletteBotTimers = [];

  // Честная физика: сначала случайные v0 (рывок) и tau (трение), потом
  // считаем, где колесо реально остановится — победный сектор это
  // СЛЕДСТВИЕ симуляции, а не то, подо что она подгоняется.
  //
  // БАГ, который тут был: v0 (18-26 рад/с) и tau (0.75-1.05 сек) давали
  // пройденный угол distance = tau*(v0 - VEND), то есть примерно 13.5-27.3
  // рад — это всего ~2.2 полных оборота колеса. При взятии по модулю 2π
  // (чтобы понять, на каком секторе остановились) такой узкий диапазон
  // покрывает круг всего пару раз, поэтому результат совсем не был
  // равномерным по 20 секторам — колесо гораздо чаще попадало в один и тот
  // же кусок круга.
  //
  // Исправление: угол приземления (localOffset) теперь берётся НАПРЯМУЮ
  // как равномерно случайное число от 0 до 2π — это гарантирует ровно
  // 1/20 шанс на каждый сектор, без всякого смещения. distance строится
  // как (случайное целое число полных оборотов) + localOffset — обороты
  // просто добавляют красивое вращение анимации и на итоговый сектор
  // никак не влияют (кратны 2π). v0 затем ВЫЧИСЛЯЕТСЯ из желаемого
  // distance и случайного tau, так что кривая скорости/торможения
  // остаётся физически честной exponential decay, просто её параметры
  // теперь подгоняются под уже отдельно и честно выбранный угол
  // остановки, а не наоборот.
  const tau = 0.5 + Math.random() * 0.9;   // сек — постоянная времени затухания (0.5-1.4)
  // Сколько оборотов пройдёт колесо — ОДНО случайное дробное число, а не
  // целое количество "лишних" кругов + отдельно докрученный остаток.
  // Раньше это было разделено на extraTurns (всегда целое) и localOffset
  // (отдельный случайный угол) — само по себе не давало смещения по
  // секторам (так как localOffset уже был равномерным), но визуально
  // ощущалось как "колесо всегда докручивает ровно до целого круга плюс
  // довесок", то есть как будто прокрут всегда одной и той же формы.
  // Теперь оборотов ровно totalTurns, без искусственного деления —
  // 3.5, 4.5, 6.2 и любое другое дробное число получаются естественно.
  //
  // Диапазоны totalTurns (3-10) и tau (0.75-1.05) были узкими — а из-за
  // того что итоговая длительность зависит от них через ЛОГАРИФМ
  // (spinDurationMs = tau*ln(v0/VEND)), даже сильно разные v0/tau на входе
  // после логарифма превращались в почти одинаковую по ощущениям
  // длительность (реально было ~5.0-8.0с почти всегда). Расширяем оба
  // диапазона (2-14 оборотов, tau 0.5-1.4с) — теперь разброс длительности
  // получается заметно шире (~3.4-10.7с): иногда резкий короткий прокрут,
  // иногда длинный затяжной, а не всегда "одно и то же на глаз".
  const totalTurns = 2 + Math.random() * 12;              // 2.0 .. 14.0 оборотов, дробно
  const distance = totalTurns * Math.PI * 2;              // угол, который пройдёт колесо, рад
  const v0 = distance / tau + ROULETTE_VEND;              // обратная формула из distance = tau*(v0 - VEND)
  const spinDurationMs = tau * Math.log(v0 / ROULETTE_VEND) * 1000;

  // Точка старта самого спина — это НЕ застывшее место с прошлого раза, а
  // то, где колесо реально находится ПРЯМО СЕЙЧАС после медленного
  // вращения на ожидании (см. ROULETTE_IDLE_OMEGA выше). За счёт этого
  // итоговая остановка зависит ещё и от того, сколько именно шло
  // ожидание — случайности в результате становится только больше.
  const idleElapsedSec = (Date.now() - rouletteBettingStartTs) / 1000;
  const startRotation = (rouletteRotation + ROULETTE_IDLE_OMEGA * idleElapsedSec) % (Math.PI * 2);
  const finalRotation = startRotation + distance;
  rouletteRotation = finalRotation % (Math.PI * 2);

  const sliceAngle = (Math.PI * 2) / ROULETTE_SECTORS.length;
  const pointerAngle = 3 * Math.PI / 2; // указатель зафиксирован сверху
  let localAngle = (pointerAngle - rouletteRotation) % (Math.PI * 2);
  if (localAngle < 0) localAngle += Math.PI * 2;
  rouletteWinIndex = Math.floor(localAngle / sliceAngle) % ROULETTE_SECTORS.length;

  rouletteSpinStartTs = Date.now();
  rouletteSpinParams = { startRotation, v0, tau, spinDurationMs };

  broadcast({
    type: 'roulette_phase', phase: 'spinning',
    startRotation, v0, tau, spinStartTs: rouletteSpinStartTs, spinDurationMs,
    winIndex: rouletteWinIndex
  });

  setTimeout(rouletteResolve, spinDurationMs + 150);
}
async function rouletteResolve() {
  const sector = ROULETTE_SECTORS[rouletteWinIndex];
  rouletteHistory.unshift(sector);
  rouletteHistory = rouletteHistory.slice(0, 12);
  for (const key of Object.keys(pendingRouletteBets)) {
    const bet = pendingRouletteBets[key];
    const u = users[key];
    delete pendingRouletteBets[key];
    if (!u) continue;
    if (bet.color === sector.c) {
      const payout = bet.amount * ROULETTE_MULT[sector.c];
      u.balance += payout;
      recordEarnings(u.username, payout - bet.amount);
    } else {
      recordEarnings(u.username, -bet.amount);
    }
    const uws = rouletteSocketsByUser[key];
    if (uws) sendTo(uws, { type: 'balance', balance: u.balance });
  }
  await saveUsers();
  await saveGameState();
  broadcast({ type: 'roulette_result', sector, history: rouletteHistory });
  rouletteStartBetting();
}


// ---------------------------------------------------------------------------
// MINES — single-player, same "client computes, server trusts with a
// sanity cap" model as Stairs: the grid/mines/reveal animation all run
// client-side, the server just holds the stake and pays out whatever
// mines_result reports — capped at the mathematically-provable maximum
// for that mine count, so a tampered client can't claim more than is
// actually possible. See minesMultiplierAt below and mines_bet/
// mines_result in the WS handler further down.
// ---------------------------------------------------------------------------
const MINES_TOTAL = 25;         // 5x5 board — MUST match MINES_GRID_N*MINES_GRID_N on the client
const MINES_HOUSE_EDGE = 0.03;
const MINES_MIN = 3, MINES_MAX = 24;
const MINES_MIN_BET = 1;
let pendingMinesBets = {}; // key -> amount staked, cleared once mines_result comes back in
const UPGRADER_RTP = 0.965;
const UPGRADER_MIN_BET = 1;
const UPGRADER_MAX_BET = 1500;
let pendingUpgraderBets = {}; // key -> {amount, chancePct, multiplier, roundId}

function minesMultiplierAt(n, mines) {
  let m = 1;
  for (let i = 0; i < n; i++) { m *= (MINES_TOTAL - i) / (MINES_TOTAL - mines - i); }
  return m * (1 - MINES_HOUSE_EDGE);
}
// The absolute ceiling for a given mine count: every single safe tile
// opened without hitting a mine. Nothing a client reports can legitimately
// exceed this, regardless of how many tiles it claims to have revealed.
function minesMaxMultiplier(mines) {
  return minesMultiplierAt(MINES_TOTAL - mines, mines);
}

// ---------------------------------------------------------------------------
// STAIRS DAILY LEADERBOARD — top 10 multipliers reached today, across all
// players. Resets at MSK midnight (same day boundary as the free daily
// crash). A new result only ever displaces an existing entry if it's
// actually higher than it — see stairsLeaderboardSubmit.
// ---------------------------------------------------------------------------
let stairsLeaderboard = []; // [{username, mult}, ...] sorted desc, length <= 10
let stairsLeaderboardDay = null;
// loadGameState() now runs inside the async bootstrap at the bottom of this
// file — it needs users{} already loaded (for the leftover-bet refund) and,
// in Mongo mode, a live connection, so it can no longer run synchronously
// here at require-time.

function stairsLeaderboardEnsureDay() {
  const today = mskDateString(Date.now());
  if (stairsLeaderboardDay !== today) {
    stairsLeaderboardDay = today;
    stairsLeaderboard = [];
  }
}
function stairsLeaderboardSubmit(username, mult) {
  stairsLeaderboardEnsureDay();
  const before = stairsLeaderboard.map(e => e.username + ':' + e.mult).join(',');
  stairsLeaderboard.push({ username, mult });
  stairsLeaderboard.sort((a, b) => b.mult - a.mult);
  stairsLeaderboard = stairsLeaderboard.slice(0, 10);
  const after = stairsLeaderboard.map(e => e.username + ':' + e.mult).join(',');
  if (after !== before) {
    broadcast({ type: 'stairs_leaderboard', top: stairsLeaderboard });
    saveGameState();
  }
}
function stairsLeaderboardCurrent() {
  stairsLeaderboardEnsureDay();
  return stairsLeaderboard;
}

// ---------------------------------------------------------------------------
// WEEKLY EARNINGS LEADERBOARD — top 50 by total real winnings this week
// (crash cashouts, stairs payouts, free-crash payouts, wheel pot wins).
// Tracks gross winnings from each winning event, not net weekly P&L against
// losses elsewhere — simplest honest reading of "who earned the most".
// ---------------------------------------------------------------------------
let weeklyEarnings = {}; // key = username.toLowerCase() -> {username, total}
let weeklyEarningsWeekKey = null;
function weeklyEarningsWeekKeyNow() {
  const d = new Date(Date.now() + 3 * 3600000); // MSK, same convention as mskDateString
  const onejan = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const week = Math.ceil((((d - onejan) / 86400000) + onejan.getUTCDay() + 1) / 7);
  return d.getUTCFullYear() + '-W' + week;
}
function weeklyEarningsEnsureWeek() {
  const wk = weeklyEarningsWeekKeyNow();
  if (weeklyEarningsWeekKey !== wk) { weeklyEarningsWeekKey = wk; weeklyEarnings = {}; }
}
function recordEarnings(username, amount) {
  if (!username || !Number.isFinite(amount) || amount <= 0) return;
  weeklyEarningsEnsureWeek();
  const key = username.toLowerCase();
  if (!weeklyEarnings[key]) weeklyEarnings[key] = { username, total: 0 };
  weeklyEarnings[key].total += amount;
  broadcast({ type: 'weekly_earnings', top: weeklyEarningsTop50() });
}
function weeklyEarningsTop50() {
  weeklyEarningsEnsureWeek();
  return Object.values(weeklyEarnings).sort((a, b) => b.total - a.total).slice(0, 50);
}

// REFERRALS — called right after a bet's stake is deducted, from every bet-placing handler below
// (crash, stairs, roulette, upgrader, mines, wheel, ball, ffa — every mode, per the 1% rule).
// Counts this bettor's own lifetime bet count; on every SECOND one, their referrer (if any) gets 1%
// of THIS bet's amount credited straight to their balance. Mutates users[] in place — the caller's
// existing `await saveUsers()` right after this call persists it, no extra write needed here.
function awardReferralOnBet(bettor, amount) {
  bettor.refBetCount = (bettor.refBetCount || 0) + 1;
  if (!bettor.refBy) return;
  const refUser = users[bettor.refBy];
  if (!refUser) return;
  if (bettor.refBetCount % 2 !== 0) return; // only every second bet pays out
  const cut = Math.round(amount * 0.01 * 100) / 100;
  if (cut <= 0) return;
  refUser.balance += cut;
  refUser.refEarnings = Math.round(((refUser.refEarnings || 0) + cut) * 100) / 100;
  const refWs = socketsByUser[bettor.refBy];
  if (refWs) sendTo(refWs, { type: 'balance', balance: refUser.balance });
}

function betsList() {
  return Object.values(bets).map(b => ({ username: b.username, amount: b.amount, status: b.status, mult: b.mult }));
}
function broadcast(obj) {
  const msg = JSON.stringify(obj);
  wss.clients.forEach(ws => { if (ws.readyState === WebSocket.OPEN) ws.send(msg); });
}
function sendTo(ws, obj) {
  if (ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify(obj));
}

// Live per-mode player counts for the hub's game badges (main/stairs/wheel
// only — matches the three cards that actually show a count instead of a
// "1/день" or "soon" badge). Each connection reports which mode it's
// currently sitting in via 'view_change' (see switchView on the client);
// this just tallies wss.clients by that field and pushes the totals out
// to everyone, so badges update live for people browsing the hub too, not
// just for whoever just switched.
function currentGameCounts() {
  const counts = { main: 0, stairs: 0, wheel: 0, ball: 0, mines: 0, ffa: 0, upgrader: 0, roulette: 0, trading: 0 };
  wss.clients.forEach(ws => {
    if (ws.readyState === WebSocket.OPEN && ws.currentGame && counts.hasOwnProperty(ws.currentGame)) {
      counts[ws.currentGame]++;
    }
  });
  return counts;
}
function broadcastGameCounts() {
  broadcast({ type: 'game_counts', counts: currentGameCounts() });
}

function startBetting() {
  phase = 'waiting';
  bets = {};
  bettingEndTs = Date.now() + BETTING_MS;
  spawnBotBets();
  broadcast({ type: 'phase', phase, bettingEndTs, bettingMs: BETTING_MS });
  saveGameState();
}
function startRunning() {
  phase = 'running';
  crashPoint = genCrashPoint();
  crashTimeSec = timeForMultiplier(crashPoint);
  roundStartTs = Date.now();
  currentMultiplier = 1;
  broadcast({ type: 'phase', phase });
}
function doCrash() {
  phase = 'crashed';
  currentMultiplier = crashPoint;
  Object.values(bets).forEach(b => {
    // If a bot's target was above this round's crashPoint, it just busts
    // here like anyone else still active — no rescue, no special case.
    if (b.status === 'active') { b.status = 'busted'; b.mult = crashPoint; }
  });
  history.unshift(crashPoint);
  history = history.slice(0, 10);
  broadcast({ type: 'crash', crashPoint, history, bets: betsList() });
  saveGameState();
  setTimeout(startBetting, 2500);
}

setInterval(() => {
  const now = Date.now();
  if (phase === 'waiting') {
    admitDueBots();
    const remain = bettingEndTs - now;
    broadcast({ type: 'tick', phase, countdownMs: Math.max(0, remain), bets: betsList(), history });
    if (remain <= 0) startRunning();
  } else if (phase === 'running') {
    const elapsed = (now - roundStartTs) / 1000;
    if (elapsed >= crashTimeSec) { doCrash(); return; }
    currentMultiplier = multiplierAtTime(elapsed);
    resolveBotCashouts();
    broadcast({ type: 'tick', phase, multiplier: currentMultiplier, bets: betsList(), history });
  }
}, 100);

// ---------------------------------------------------------------------------
// WEBSOCKET HANDLING
// ---------------------------------------------------------------------------
wss.on('connection', (ws) => {
  let authed = null; // username key
  let freeRoundTimer = null;
  let freeRoundStartTimeout = null; // pending "reel spin -> pause -> actually start" delay, see 'freecrash_start' below
  let freeRound = null; // {crashPoint, crashTimeSec, startTs, resolved, amount} — also set to {pending:true, amount} during the reel+pause window, before the round proper begins
  ws.currentGame = null; // which live-tracked mode (main/stairs/wheel) this connection is currently viewing, if any

  function clearFreeRound() {
    if (freeRoundTimer) { clearInterval(freeRoundTimer); freeRoundTimer = null; }
    if (freeRoundStartTimeout) { clearTimeout(freeRoundStartTimeout); freeRoundStartTimeout = null; }
    freeRound = null;
  }

  function freeCrashStatus(user) {
    const today = mskDateString(Date.now());
    const usedToday = user.lastFreeCrashDate === today;
    return { available: !usedToday && !freeRound, nextResetAt: usedToday ? mskNextMidnightISO() : null };
  }

  ws.on('message', async (raw) => {
    let msg;
    try { msg = JSON.parse(raw); } catch (e) { return; }

    try {
    if (msg.type === 'view_change') {
      const allowed = { main: 1, stairs: 1, wheel: 1, ball: 1, mines: 1, ffa: 1, upgrader: 1, roulette: 1, trading: 1 };
      ws.currentGame = (msg.game && allowed[msg.game]) ? msg.game : null;
      broadcastGameCounts();
      return;
    }
    if (msg.type === 'auth') {
      const key = verifyToken(msg.token);
      if (key) {
        authed = key;
        wheelSocketsByUser[key] = ws;
        ballSocketsByUser[key] = ws;
        ffaSocketsByUser[key] = ws;
        rouletteSocketsByUser[key] = ws;
        socketsByUser[key] = ws;
        const user = users[key];
        sendTo(ws, { type: 'authed', username: user.username, balance: user.balance, tcoin: user.tcoin || 0, tcoinAvgBuy: user.tcoinAvgBuy || 0 });
        sendTo(ws, { type: 'game_counts', counts: currentGameCounts() });
        sendTo(ws, { type: 'stairs_leaderboard', top: stairsLeaderboardCurrent() });
        sendTo(ws, { type: 'weekly_earnings', top: weeklyEarningsTop50() });
        sendTo(ws, { type: 'phase', phase, bettingEndTs, bettingMs: BETTING_MS });
        sendTo(ws, { type: 'tick', phase, multiplier: currentMultiplier, bets: betsList(), history });
        sendTo(ws, { type: 'freecrash_status', ...freeCrashStatus(user) });
        if (roulettePhase === 'betting') {
          sendTo(ws, {
            type: 'roulette_phase', phase: 'betting',
            bettingEndTs: rouletteBettingEndTs, bettingStartTs: rouletteBettingStartTs,
            restRotation: rouletteRotation, idleOmega: ROULETTE_IDLE_OMEGA,
            history: rouletteHistory
          });
          sendTo(ws, { type: 'roulette_bets_snapshot', bets: Object.values(rouletteBets) });
        } else if (roulettePhase === 'spinning' && rouletteSpinParams) {
          sendTo(ws, {
            type: 'roulette_phase', phase: 'spinning',
            startRotation: rouletteSpinParams.startRotation, v0: rouletteSpinParams.v0, tau: rouletteSpinParams.tau,
            spinStartTs: rouletteSpinStartTs, spinDurationMs: rouletteSpinParams.spinDurationMs,
            winIndex: rouletteWinIndex
          });
        }
        if (wheelPhase === 'betting') {
          wheelBiggestWinEnsureDay();
          sendTo(ws, { type: 'wheel_round_start', bets: wheelBetsList(), history: wheelHistory, biggestWin: wheelBiggestWin });
          if (wheelCountdownStarted) {
            sendTo(ws, { type: 'wheel_bet_update', bets: wheelBetsList(), bettingEndTs: wheelBettingEndTs, countdownStarted: true });
          }
        } else if (wheelPhase === 'spinning') {
          sendTo(ws, {
            type: 'wheel_spin_start', bets: wheelBetsList(),
            spinStartTs: wheelSpinStartTs, spinDurationMs: wheelSpinDurationMs,
            spinStartRotation: wheelSpinStartRotation, spinTargetRotation: wheelSpinTargetRotation
          });
        }
        ballBiggestWinEnsureDay();
        sendTo(ws, { type: 'ball_round_start', bets: ballBetsList(), history: ballHistory, biggestWin: ballBiggestWin });
        if (ballPhase === 'betting' && ballCountdownStarted) {
          sendTo(ws, { type: 'ball_bet_update', bets: ballBetsList(), bettingEndTs: ballBettingEndTs, countdownStarted: true, sites: ballSites });
        }
        ffaBiggestWinEnsureDay();
        sendTo(ws, { type: 'ffa_round_start', bets: ffaBetsList(), history: ffaHistory, biggestWin: ffaBiggestWin });
        if (ffaPhase === 'betting' && ffaCountdownStarted) {
          sendTo(ws, { type: 'ffa_bet_update', bets: ffaBetsList(), bettingEndTs: ffaBettingEndTs, countdownStarted: true });
        } else if (ffaPhase === 'arming' || ffaPhase === 'combat') {
          // Mid-round join/reconnect — hand the newcomer the live snapshot
          // so their canvas isn't just stuck on the betting screen.
          sendTo(ws, {
            type: 'ffa_arm',
            players: ffaPlayers.map(p => ({ username: p.username, color: p.color, amount: p.amount, avatarUrl: p.avatarUrl, x: p.x, y: p.y, r: p.r, alive: p.alive })),
            armMs: 0
          });
        }
      } else {
        // Distinct from a generic in-game error: tells the client this token
        // is dead and it should drop back to the login screen instead of
        // sitting on a broken page.
        sendTo(ws, { type: 'auth_error', error: 'Сессия недействительна, войдите заново' });
      }
      return;
    }
    if (!authed) {
      sendTo(ws, { type: 'auth_error', error: 'Сессия недействительна, войдите заново' });
      return;
    }
    const user = users[authed];

    // ----- MAIN ROUND -----
    if (msg.type === 'bet') {
      if (phase !== 'waiting') return sendTo(ws, { type: 'error', error: 'Ставки уже закрыты' });
      if (bets[authed]) return sendTo(ws, { type: 'error', error: 'Ставка уже сделана' });
      const amount = Math.floor(Number(msg.amount) * 100) / 100;
      if (!amount || amount < CRASH_MIN_BET || amount > user.balance) {
        return sendTo(ws, { type: 'error', error: 'Некорректная сумма ставки' });
      }
      user.balance -= amount;
      awardReferralOnBet(user, amount);
      await saveUsers();
      bets[authed] = { username: user.username, amount, status: 'active', mult: null };
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
      broadcast({ type: 'tick', phase, countdownMs: Math.max(0, bettingEndTs - Date.now()), bets: betsList(), history });
    }

    if (msg.type === 'cashout') {
      if (phase !== 'running') return;
      const b = bets[authed];
      if (!b || b.status !== 'active') return;
      b.status = 'cashed';
      b.mult = currentMultiplier;
      user.balance += b.amount * currentMultiplier;
      recordEarnings(user.username, b.amount * (currentMultiplier - 1));
      await saveUsers();
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
      broadcast({ type: 'tick', phase, multiplier: currentMultiplier, bets: betsList(), history });
    }

    // ----- STAIRS ("Лестница") -----
    // The throw itself (aim, physics, which steps get touched) is still
    // simulated entirely client-side — only the balance change is made
    // authoritative here, the same pattern as 'bet'/'cashout' above, so a
    // page reload can no longer "lose" a stairs bet or its payout (the
    // client used to just mutate its own local `balance` variable and
    // never tell the server, so a reload re-fetched the pre-bet balance).
    if (msg.type === 'stairs_bet') {
      const amount = Math.floor(Number(msg.amount) * 100) / 100;
      if (!amount || amount < 1 || amount > 1500 || amount > user.balance) {
        return sendTo(ws, { type: 'error', error: 'Некорректная сумма ставки' });
      }
      user.balance -= amount;
      awardReferralOnBet(user, amount);
      await saveUsers();
      pendingStairsBets[authed] = amount;
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
    }

    if (msg.type === 'stairs_result') {
      const payout = Number(msg.payout);
      // A negative payout is now legitimate — it means the run ended while
      // a spikes step still had the multiplier in the red (see the spikes
      // step type client-side), so the player owes MORE than just the
      // stake already deducted at stairs_bet. Still clamped so the balance
      // itself can never go below 0 from this.
      if (!Number.isFinite(payout)) return;
      user.balance = Math.max(0, user.balance + payout);
      recordEarnings(user.username, payout - (pendingStairsBets[authed] || 0));
      // Black hole: the bet gets charged a SECOND time on top of the one
      // already staked at stairs_bet — using the server's own recorded
      // stake (pendingStairsBets), never a client-supplied amount, and
      // clamped so the balance can never go negative from this.
      if (msg.blackHole) {
        const staked = pendingStairsBets[authed];
        if (Number.isFinite(staked)) {
          user.balance = Math.max(0, user.balance - staked);
        }
      }
      delete pendingStairsBets[authed];
      await saveUsers();
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });

      const mult = Number(msg.mult);
      if (Number.isFinite(mult) && mult > 0) {
        stairsLeaderboardSubmit(user.username, mult);
      }
    }

    // ----- ROULETTE -----
    // Server-authoritative again, but honestly this time: the server ran
    // the actual physics simulation (see the ROULETTE section near the
    // top) and only READ OFF the winning sector from where it stopped —
    // it never picks a color first and works backwards. The client here
    // only ever sends its bet; the payout is settled automatically by
    // rouletteResolve() once the spin (which every client is replaying
    // identically) finishes.
    if (msg.type === 'roulette_bet') {
      if (roulettePhase !== 'betting') return sendTo(ws, { type: 'error', error: 'Ставки уже закрыты' });
      if (pendingRouletteBets[authed]) return sendTo(ws, { type: 'error', error: 'Ставка уже сделана' });
      const color = String(msg.color || '');
      if (!ROULETTE_MULT.hasOwnProperty(color)) return sendTo(ws, { type: 'error', error: 'Неизвестный цвет' });
      const amount = Math.floor(Number(msg.amount) * 100) / 100;
      if (!amount || amount < ROULETTE_MIN_BET || amount > 5000 || amount > user.balance) {
        return sendTo(ws, { type: 'error', error: 'Некорректная сумма ставки' });
      }
      user.balance -= amount;
      awardReferralOnBet(user, amount);
      const bet = { username: user.username, color, amount };
      pendingRouletteBets[authed] = { color, amount };
      rouletteBets[user.username] = bet;
      await saveUsers();
      sendTo(ws, { type: 'balance', balance: user.balance });
      broadcast({ type: 'roulette_bet_added', bet });
    }

    // ----- UPGRADER ("Апгрейдер") -----
    // The client determines the result from the actual physics/landing cell.
    // The server only holds the stake and settles the client-reported result.
    if (msg.type === 'upgrader_bet') {
      if (pendingUpgraderBets[authed]) {
        return sendTo(ws, { type: 'error', error: 'Раунд апгрейдора уже идёт' });
      }
      const amount = Math.floor(Number(msg.amount) * 100) / 100;
      const chancePct = Math.floor(Number(msg.chance));
      if (!Number.isFinite(amount) || amount < UPGRADER_MIN_BET || amount > UPGRADER_MAX_BET || amount > user.balance) {
        return sendTo(ws, { type: 'error', error: 'Некорректная сумма ставки' });
      }
      if (!Number.isInteger(chancePct) || chancePct < 5 || chancePct > 80) {
        return sendTo(ws, { type: 'error', error: 'Некорректный шанс' });
      }
      const multiplier = UPGRADER_RTP / (chancePct / 100);
      const roundId = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
      user.balance -= amount;
      awardReferralOnBet(user, amount);
      pendingUpgraderBets[authed] = { amount, chancePct, multiplier, roundId };
      await saveUsers();
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
      sendTo(ws, { type: 'upgrader_start', roundId, chancePct, multiplier });
      return;
    }

    if (msg.type === 'upgrader_result') {
      const pending = pendingUpgraderBets[authed];
      if (!pending || msg.roundId !== pending.roundId) return;
      const won = msg.won === true;
      const payout = won ? Math.round(pending.amount * pending.multiplier * 100) / 100 : 0;
      user.balance += payout;
      if (payout > 0) recordEarnings(user.username, payout - pending.amount);
      delete pendingUpgraderBets[authed];
      await saveUsers();
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
      sendTo(ws, { type: 'upgrader_finished', roundId: pending.roundId, payout, won });
      return;
    }

    // ----- MINES -----
    // Grid + mine positions + reveal logic all live client-side (same
    // trust model as Stairs above) — this only validates the bet, holds
    // the stake, and on mines_result pays out whatever's reported, capped
    // at the mathematically-provable ceiling for that mine count.
    if (msg.type === 'mines_bet') {
      const amount = Math.floor(Number(msg.amount) * 100) / 100;
      const mines = Math.floor(Number(msg.mines));
      if (!amount || amount < MINES_MIN_BET || amount > 1500 || amount > user.balance) {
        return sendTo(ws, { type: 'error', error: 'Некорректная сумма ставки' });
      }
      if (!Number.isInteger(mines) || mines < MINES_MIN || mines > MINES_MAX) {
        return sendTo(ws, { type: 'error', error: 'Некорректное число мин' });
      }
      user.balance -= amount;
      awardReferralOnBet(user, amount);
      await saveUsers();
      pendingMinesBets[authed] = amount;
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
    }

    if (msg.type === 'mines_result') {
      const payout = Number(msg.payout);
      const mines = Math.floor(Number(msg.mines));
      const staked = pendingMinesBets[authed];
      if (staked === undefined) return; // no matching bet on record (bet never went through) — nothing to resolve
      if (!Number.isFinite(payout) || payout < 0) { delete pendingMinesBets[authed]; return; }
      if (Number.isInteger(mines) && mines >= MINES_MIN && mines <= MINES_MAX) {
        const cap = staked * minesMaxMultiplier(mines) + 0.01;
        if (payout > cap) { delete pendingMinesBets[authed]; return; } // provably impossible for this mine count — reject outright
      }
      user.balance += payout;
      recordEarnings(user.username, payout - staked);
      delete pendingMinesBets[authed];
      await saveUsers();
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
    }

    // ----- WHEEL OF FORTUNE ("Колесо фортуны") -----
    // The round itself (timer, spin target, winner) is fully server-driven
    // and shared — this handler only validates the bet and deducts the
    // stake; wheelPlaceBet (see above) handles the round-state side and
    // broadcasts the result to everyone.
    if (msg.type === 'wheel_bet') {
      if (wheelPhase !== 'betting') return sendTo(ws, { type: 'error', error: 'Ставки сейчас закрыты' });
      if ((wheelAddCounts[authed] || 0) >= WHEEL_MAX_ADDS) {
        return sendTo(ws, { type: 'error', error: 'Максимум ' + WHEEL_MAX_ADDS + ' добавлений ставки за раунд' });
      }
      const amount = Math.floor(Number(msg.amount) * 100) / 100;
      if (!amount || amount < WHEEL_MIN_BET || amount > user.balance) {
        return sendTo(ws, { type: 'error', error: 'Некорректная сумма ставки' });
      }
      user.balance -= amount;
      awardReferralOnBet(user, amount);
      wheelAddCounts[authed] = (wheelAddCounts[authed] || 0) + 1;
      pendingWheelBets[authed] = Math.round(((pendingWheelBets[authed] || 0) + amount) * 100) / 100;
      await saveUsers();
      wheelPlaceBet(authed, user.username, amount);
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
    }
    if (msg.type === 'ball_bet') {
      if (ballPhase !== 'betting') return sendTo(ws, { type: 'error', error: 'Ставки сейчас закрыты' });
      if ((ballAddCounts[authed] || 0) >= BALL_MAX_ADDS) {
        return sendTo(ws, { type: 'error', error: 'Максимум ' + BALL_MAX_ADDS + ' добавлений ставки за раунд' });
      }
      const amount = Math.floor(Number(msg.amount) * 100) / 100;
      if (!amount || amount < BALL_MIN_BET || amount > user.balance) {
        return sendTo(ws, { type: 'error', error: 'Некорректная сумма ставки' });
      }
      user.balance -= amount;
      awardReferralOnBet(user, amount);
      ballAddCounts[authed] = (ballAddCounts[authed] || 0) + 1;
      pendingBallBets[authed] = Math.round(((pendingBallBets[authed] || 0) + amount) * 100) / 100;
      await saveUsers();
      ballPlaceBet(authed, user.username, amount);
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
    }

    // ----- TRADING ("T Coin") -----
    // No bets/rounds here — trading_buy/trading_sell execute immediately
    // against the live pool (see TRADING section above). trading_get_state
    // lets a client fetch a full snapshot when it opens the screen, since
    // the periodic trading_tick broadcast only carries the fast-moving bits.
    if (msg.type === 'trading_get_state') {
      const snap = tradingSnapshot();
      sendTo(ws, { type: 'trading_state', ...snap, myTcoin: user.tcoin || 0, myAvgBuy: user.tcoinAvgBuy || 0 });
    }
    if (msg.type === 'trading_buy') {
      const amount = Math.floor(Number(msg.amount) * 100) / 100;
      if (!amount || amount <= 0) return sendTo(ws, { type: 'error', error: 'Некорректная сумма' });
      if (amount > user.balance) return sendTo(ws, { type: 'error', error: 'Недостаточно средств — на балансе ' + user.balance.toFixed(2) });
      const pool = tradingMainPool();
      const maxTrade = pool * TRADING_MAX_POOL_RATIO;
      if (amount > maxTrade) return sendTo(ws, { type: 'error', error: 'Слишком крупная сделка — не более ' + maxTrade.toFixed(2) + ' R за раз' });
      const price = tradingPrice(pool);
      const coinsOut = tradingSimulateBuy(pool, amount);
      const tcoinBefore = user.tcoin || 0;
      user.balance = Math.round((user.balance - amount) * 100) / 100;
      user.tcoin = Math.round((tcoinBefore + coinsOut) * 10000) / 10000;
      user.tcoinAvgBuy = user.tcoin > 0 ? ((user.tcoinAvgBuy || 0) * tcoinBefore + amount) / user.tcoin : 0;
      await saveUsers();
      tradingRecordTrade(authed, user.username, 'buy', coinsOut, price, null, amount);
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
      sendTo(ws, { type: 'tcoin', tcoin: user.tcoin, avgBuy: user.tcoinAvgBuy });
    }
    if (msg.type === 'trading_sell') {
      const amount = Math.floor(Number(msg.amount) * 10000) / 10000;
      if (!amount || amount <= 0) return sendTo(ws, { type: 'error', error: 'Некорректная сумма' });
      if (amount > (user.tcoin || 0)) return sendTo(ws, { type: 'error', error: 'Недостаточно T Coin — на балансе ' + (user.tcoin || 0).toFixed(4) });
      const pool = tradingMainPool();
      const maxTrade = (pool * TRADING_MAX_POOL_RATIO) / tradingPrice(pool);
      if (amount > maxTrade) return sendTo(ws, { type: 'error', error: 'Слишком крупная сделка — не более ' + maxTrade.toFixed(4) + ' T Coin за раз' });
      const price = tradingPrice(pool);
      const mainOut = tradingSimulateSell(pool, amount);
      const pnl = user.tcoinAvgBuy > 0 ? ((price - user.tcoinAvgBuy) / user.tcoinAvgBuy * 100) : 0;
      user.tcoin = Math.round(((user.tcoin || 0) - amount) * 10000) / 10000;
      if (user.tcoin < 0.0001) { user.tcoin = 0; user.tcoinAvgBuy = 0; }
      user.balance = Math.round((user.balance + mainOut) * 100) / 100;
      await saveUsers();
      tradingRecordTrade(authed, user.username, 'sell', amount, price, pnl, mainOut);
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
      sendTo(ws, { type: 'tcoin', tcoin: user.tcoin, avgBuy: user.tcoinAvgBuy });
    }

    // ----- FFA ARENA ("FFA Арена") -----
    // Same shape as Ball of Fate's bet handler: validate + deduct here,
    // ffaPlaceBet (see above) handles the round-state side. The actual
    // winner is never chosen here or anywhere server-side — it falls out
    // of the physics simulation once betting closes.
    if (msg.type === 'ffa_bet') {
      if (ffaPhase !== 'betting') return sendTo(ws, { type: 'error', error: 'Ставки сейчас закрыты' });
      if ((ffaAddCounts[authed] || 0) >= FFA_MAX_ADDS) {
        return sendTo(ws, { type: 'error', error: 'Максимум ' + FFA_MAX_ADDS + ' добавлений ставки за раунд' });
      }
      const amount = Math.floor(Number(msg.amount) * 100) / 100;
      if (!amount || amount < FFA_MIN_BET || amount > user.balance) {
        return sendTo(ws, { type: 'error', error: 'Некорректная сумма ставки' });
      }
      user.balance -= amount;
      awardReferralOnBet(user, amount);
      ffaAddCounts[authed] = (ffaAddCounts[authed] || 0) + 1;
      pendingFfaBets[authed] = Math.round(((pendingFfaBets[authed] || 0) + amount) * 100) / 100;
      await saveUsers();
      ffaPlaceBet(authed, user.username, amount);
      await saveGameState();
      sendTo(ws, { type: 'balance', balance: user.balance });
    }

    // ----- FREE DAILY CRASH (solo, isolated round, sent only to this socket) -----
    // Now a two-step start: 'freecrash_start' first rolls the bet-reel
    // amount and sends 'freecrash_reel' so the client can play the spin
    // animation, then — only after the reel's own spin duration PLUS the
    // requested 3s pause — the round itself actually begins and
    // 'freecrash_started' goes out. freeRound is set (as {pending:true})
    // the instant the reel rolls, not when the round starts, so a second
    // click during the spin/pause window is correctly rejected as
    // "already running" instead of rolling a second reel.
    if (msg.type === 'freecrash_start') {
      const today = mskDateString(Date.now());
      if (user.lastFreeCrashDate === today) {
        return sendTo(ws, { type: 'freecrash_status', ...freeCrashStatus(user) });
      }
      if (freeRound) return; // already running (reel spinning, paused, or round in flight)
      user.lastFreeCrashDate = today; // consumed immediately, no re-tries today

      const amount = pickFreeReelAmount();
      freeRound = { pending: true, amount, resolved: false };
      await saveUsers();
      sendTo(ws, { type: 'freecrash_reel', amount });

      freeRoundStartTimeout = setTimeout(() => {
        freeRoundStartTimeout = null;
        if (!freeRound || !freeRound.pending) return; // disconnected/cleared mid-wait
        const cp = genCrashPoint();
        const ct = timeForMultiplier(cp);
        freeRound = { crashPoint: cp, crashTimeSec: ct, startTs: Date.now(), resolved: false, amount };
        sendTo(ws, { type: 'freecrash_started', amount });

        freeRoundTimer = setInterval(() => {
          if (!freeRound || freeRound.resolved) return;
          const elapsed = (Date.now() - freeRound.startTs) / 1000;
          if (elapsed >= freeRound.crashTimeSec) {
            freeRound.resolved = true;
            sendTo(ws, { type: 'freecrash_crash', crashPoint: freeRound.crashPoint });
            sendTo(ws, { type: 'freecrash_status', ...freeCrashStatus(user) });
            clearFreeRound();
            return;
          }
          const m = multiplierAtTime(elapsed);
          sendTo(ws, { type: 'freecrash_tick', multiplier: m });
        }, 100);
      }, FREE_REEL_SPIN_MS + FREE_REEL_PAUSE_MS);
    }

    if (msg.type === 'freecrash_cashout') {
      if (!freeRound || freeRound.pending || freeRound.resolved) return;
      const elapsed = (Date.now() - freeRound.startTs) / 1000;
      if (elapsed >= freeRound.crashTimeSec) return; // too late, already crashed
      const m = multiplierAtTime(elapsed);
      if (m < FREE_MIN_CASHOUT_MULT) {
        return sendTo(ws, { type: 'freecrash_too_early', minMult: FREE_MIN_CASHOUT_MULT, multiplier: m });
      }
      freeRound.resolved = true;
      const payout = freeRound.amount * m;
      user.balance += payout;
      recordEarnings(user.username, payout);
      await saveUsers();
      sendTo(ws, { type: 'freecrash_result', multiplier: m, payout, amount: freeRound.amount });
      sendTo(ws, { type: 'balance', balance: user.balance });
      sendTo(ws, { type: 'freecrash_status', ...freeCrashStatus(user) });
      clearFreeRound();
    }

    if (msg.type === 'freecrash_check') {
      sendTo(ws, { type: 'freecrash_status', ...freeCrashStatus(user) });
    }
    } catch (err) {
      // A bug in any branch above used to be an UNCAUGHT exception here,
      // which crashes the whole Node process — every connected player's
      // round, balance, and connection along with it — and most hosts
      // (Bonto included) then auto-restart the process to keep the site
      // reachable. That auto-restart is very likely what looked like
      // "Bonto randomly restarts the site while I'm playing": it wasn't
      // random or Bonto's doing, it was this server crashing on some edge
      // case and the platform quietly bringing it back up. Logging here
      // instead means one bad message degrades gracefully (that one
      // action just doesn't complete) instead of taking the whole server
      // down for everyone.
      console.error('Error handling ws message:', msg && msg.type, err);
    }
  });

  ws.on('close', () => {
    clearFreeRound();
    if (authed && wheelSocketsByUser[authed] === ws) delete wheelSocketsByUser[authed];
    if (authed && ballSocketsByUser[authed] === ws) delete ballSocketsByUser[authed];
    if (authed && ffaSocketsByUser[authed] === ws) delete ffaSocketsByUser[authed];
    if (authed && socketsByUser[authed] === ws) delete socketsByUser[authed];
    if (ws.currentGame) broadcastGameCounts();
  });
});

const PORT = process.env.PORT || 3000;
async function bootstrap() {
  await connectMongo();          // no-op (file mode) if MONGODB_URI isn't set
  await loadOrCreateSecret();
  await loadUsers();
  if (backfillTCoin()) await saveUsers();
  await loadGameState();         // needs users{} already loaded, for the leftover-bet refund
  startBetting();
  wheelStartBettingRound();
  ballStartBettingRound();
  ffaStartBettingRound();
  rouletteStartBetting();
  tradingEnsureK();
  setInterval(tradingTick, TRADING_TICK_MS);
  await registerTelegramWebhook(); // Telegram Stars deposits need this to actually get credited — see /telegram/webhook above
  server.listen(PORT, () => console.log('Crash server listening on port', PORT));
}

// Points Telegram at our own /telegram/webhook so successful_payment /
// pre_checkout_query updates actually reach us. Needs the bot token AND a
// real public URL for this instance (Render sets RENDER_EXTERNAL_URL
// automatically; PUBLIC_URL is there as a manual override for any other
// host). Never fatal if it fails — deposits just won't get credited until
// it's set up right, everything else in the app keeps working.
function getPublicUrl() {
  const u = process.env.PUBLIC_URL || process.env.RENDER_EXTERNAL_URL || '';
  return u ? u.replace(/\/$/, '') : null;
}

async function registerTelegramWebhook() {
  const botToken = process.env.TELEGRAM_BOT_TOKEN;
  const publicUrl = getPublicUrl();
  if (!botToken) { console.log('TELEGRAM_BOT_TOKEN not set — Telegram login AND Stars deposits are both disabled.'); return; }
  if (!publicUrl) { console.log('No PUBLIC_URL/RENDER_EXTERNAL_URL set — Telegram Stars deposits will not be credited (webhook not registered). Telegram login still works fine.'); return; }
  try {
    const params = { url: `${publicUrl.replace(/\/$/, '')}/telegram/webhook`, allowed_updates: ['pre_checkout_query', 'message', 'callback_query'] };
    if (process.env.TELEGRAM_WEBHOOK_SECRET) params.secret_token = process.env.TELEGRAM_WEBHOOK_SECRET;
    await telegramApiCall('setWebhook', params);
    console.log('Telegram webhook registered at', params.url);
  } catch (e) {
    console.log('Failed to register Telegram webhook:', e.message);
  }
  // Populates the little "/" square next to the chat input with our
  // commands — this is the only way to get /trade listed there, it has
  // nothing to do with setWebhook above.
  try {
    await telegramApiCall('setMyCommands', {
      commands: [{ command: 'trade', description: 'Курс T Coin и быстрая покупка/продажа' }]
    });
  } catch (e) {
    console.log('Failed to register bot commands:', e.message);
  }
}
bootstrap();

// Last-resort safety nets. Without these, ANY uncaught error anywhere in
// the process — not just inside the ws message handler above, which now
// has its own try/catch — takes the whole Node process down, and the
// host (Bonto included) then auto-restarts it to keep the site reachable.
// That silent crash+restart cycle is almost certainly what looked like
// "the site randomly restarts while I'm playing." These just log the
// error and keep the process alive instead.
process.on('uncaughtException', (err) => {
  console.error('Uncaught exception (server kept running):', err);
});
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled promise rejection (server kept running):', reason);
});

// A platform-triggered restart (a redeploy, a container recycle — Bonto
// sends SIGTERM for these, they don't go through uncaughtException above)
// used to just kill the process outright. Any bet whose round hadn't
// resolved yet (main crash: placed but not yet cashed out or busted;
// stairs: staked but the client's run hadn't reported stairs_result back)
// lived only in memory — bets{}/pendingStairsBets{} — so the stake the
// player had already paid simply vanished with no payout and no refund.
// That's what looked like "money stopped being credited." This refunds
// every such stake back to its owner's saved balance before the process
// actually exits.
async function refundUnresolvedBetsOnShutdown() {
  for (const key of Object.keys(bets)) {
    const b = bets[key];
    if (b && b.status === 'active' && users[key]) {
      users[key].balance += b.amount;
    }
  }
  for (const key of Object.keys(pendingStairsBets)) {
    if (users[key]) {
      users[key].balance += pendingStairsBets[key];
    }
  }
  for (const key of Object.keys(pendingWheelBets)) {
    if (users[key]) {
      users[key].balance += pendingWheelBets[key];
    }
  }
  for (const key of Object.keys(pendingMinesBets)) {
    if (users[key]) {
      const v = pendingMinesBets[key];
      users[key].balance += Number(v?.amount ?? v) || 0;
    }
  }
  for (const key of Object.keys(pendingUpgraderBets)) {
    if (users[key]) {
      users[key].balance += Number(pendingUpgraderBets[key]?.amount) || 0;
    }
  }
  await saveUsers();
  // Clear them before the state file is written below — otherwise the
  // startup safety net in loadGameState() would read these same 'active'
  // entries back on next boot and refund them a second time.
  bets = {};
  pendingStairsBets = {};
  pendingWheelBets = {};
  pendingMinesBets = {};
  pendingUpgraderBets = {};
  await saveGameState();
}
async function gracefulShutdown(signal) {
  console.log(`[shutdown] ${signal} received — refunding unresolved bets before exit`);
  try { await refundUnresolvedBetsOnShutdown(); } catch (e) { console.error('[shutdown] refund failed:', e); }
  process.exit(0);
}
process.on('SIGTERM', () => { gracefulShutdown('SIGTERM'); });
process.on('SIGINT', () => { gracefulShutdown('SIGINT'); });
